/* Five useful sentences per day. Generated file. */
window.TAEGLICH = [{"day":1,"theme":"Meinung sagen","theme_fa":"بیان نظر","s":[{"de":"Meiner Meinung nach sollten wir das Projekt noch einmal gründlich überdenken.","fa":"به نظر من باید یک بار دیگر پروژه را با دقت بازنگری کنیم.","note":"بعد از «Meiner Meinung nach» فعل بلافاصله در جایگاه دوم می‌آید."},{"de":"Ich bin fest davon überzeugt, dass sich die Mühe am Ende lohnt.","fa":"کاملاً مطمئنم که این زحمت در نهایت ارزشش را دارد.","note":"«überzeugt sein von + Dativ»؛ با «davon ..., dass» جمله‌ی کامل می‌سازد."},{"de":"Ehrlich gesagt halte ich nicht besonders viel von dieser Idee.","fa":"راستش را بخواهید، نظر چندان مثبتی درباره‌ی این ایده ندارم.","note":"«viel/wenig halten von» یعنی نظر خوب یا بد داشتن درباره‌ی چیزی؛ مؤدبانه و رایج."},{"de":"So wie ich das sehe, gibt es eigentlich nur zwei realistische Möglichkeiten.","fa":"آن‌طور که من می‌بینم، در واقع فقط دو راه واقع‌بینانه وجود دارد.","note":"«So wie ich das sehe» در بحث‌های شفاهی و جلسات بسیار طبیعی است."},{"de":"Ich finde es wichtig, dass alle Beteiligten mitreden dürfen.","fa":"به نظرم مهم است که همه‌ی افراد درگیر بتوانند نظر بدهند.","note":"«Ich finde es + صفت, dass ...» ساختاری ساده و پرکاربرد برای بیان نظر است."}]},{"day":2,"theme":"Zustimmen und widersprechen","theme_fa":"موافقت و مخالفت","s":[{"de":"Da bin ich ganz Ihrer Meinung.","fa":"در این مورد کاملاً با شما هم‌نظرم.","note":"رسمی است؛ در حالت دوستانه بگویید: «Da bin ich ganz deiner Meinung.»"},{"de":"Das sehe ich genauso, aber man sollte auch die Kosten bedenken.","fa":"من هم همین‌طور فکر می‌کنم، ولی باید هزینه‌ها را هم در نظر گرفت.","note":"موافقت همراه با افزودن یک نکته؛ «man sollte» لحن را نرم می‌کند."},{"de":"Da muss ich Ihnen leider widersprechen.","fa":"متأسفانه در این مورد باید با شما مخالفت کنم.","note":"«widersprechen» با Dativ می‌آید؛ مخالفت مؤدبانه در جلسه یا بحث رسمی."},{"de":"Im Prinzip haben Sie recht, trotzdem habe ich da ein paar Bedenken.","fa":"اصولاً حق با شماست، با این حال چند نگرانی دارم.","note":"«Bedenken haben» یعنی تردید یا نگرانی داشتن؛ مخالفتی نرم و دیپلماتیک."},{"de":"Das stimmt so nicht ganz, wenn du mich fragst.","fa":"اگر نظر من را بخواهی، این کاملاً درست نیست.","note":"غیررسمی است؛ «nicht ganz» مخالفت را ملایم‌تر می‌کند."}]},{"day":3,"theme":"Höfliche Bitten","theme_fa":"درخواست‌های مؤدبانه","s":[{"de":"Könnten Sie mir bitte kurz dabei helfen?","fa":"ممکن است لطفاً یک لحظه در این کار کمکم کنید؟","note":"«könnten» (Konjunktiv II) درخواست را مؤدبانه‌تر از «können» می‌کند."},{"de":"Würde es Ihnen etwas ausmachen, das Fenster zu schließen?","fa":"زحمتی برایتان ندارد پنجره را ببندید؟","note":"بسیار مؤدبانه؛ پاسخ مثبت «Nein, gar nicht» است، یعنی «نه، اصلاً زحمتی نیست»."},{"de":"Ich hätte eine kleine Bitte an Sie.","fa":"یک خواهش کوچک از شما داشتم.","note":"شروعی مؤدبانه پیش از مطرح کردن درخواست؛ ساختار: «eine Bitte an jemanden haben»."},{"de":"Wäre es möglich, die Unterlagen bis Freitag zu bekommen?","fa":"امکانش هست مدارک را تا جمعه دریافت کنم؟","note":"مناسب ایمیل و مکالمه‌ی رسمی؛ ساختار: «Wäre es möglich, ... zu + Infinitiv»."},{"de":"Kannst du mir mal kurz dein Ladekabel leihen?","fa":"می‌شود یک لحظه شارژرت را به من قرض بدهی؟","note":"غیررسمی؛ «mal» و «kurz» درخواست را دوستانه و سبک می‌کنند."}]},{"day":4,"theme":"Small Talk","theme_fa":"گپ کوتاه و دوستانه","s":[{"de":"Und, wie war Ihr Wochenende?","fa":"خب، آخر هفته‌تان چطور گذشت؟","note":"شروع رایج گفت‌وگو در محیط کار، معمولاً دوشنبه‌ها."},{"de":"Ganz schön kalt heute, oder?","fa":"امروز حسابی سرد است، نه؟","note":"حرف زدن درباره‌ی هوا رایج‌ترین موضوع گپ است؛ «oder?» تأیید طرف را می‌خواهد."},{"de":"Arbeiten Sie schon lange hier?","fa":"خیلی وقت است اینجا کار می‌کنید؟","note":"سؤالی ساده برای آشنایی با همکار جدید؛ با «schon lange» زمان حال به‌کار می‌رود."},{"de":"Haben Sie schon Pläne für den Urlaub?","fa":"برای تعطیلات برنامه‌ای دارید؟","note":"موضوعی امن و دوستانه؛ آلمانی‌ها درباره‌ی سفر زیاد حرف می‌زنند."},{"de":"Schön, Sie mal wiederzusehen! Wie geht's Ihnen denn so?","fa":"چه خوب که دوباره می‌بینمتان! حالتان چطور است؟","note":"«denn so» سؤال را صمیمی و طبیعی می‌کند."}]},{"day":5,"theme":"Telefonieren","theme_fa":"تلفن زدن","s":[{"de":"Guten Tag, hier spricht Ahmadi. Ich rufe wegen meiner Bewerbung an.","fa":"روز بخیر، احمدی هستم. درباره‌ی درخواست کارم تماس می‌گیرم.","note":"در آلمان پشت تلفن اول نام خانوادگی خود را می‌گویند؛ «wegen» با Genitiv."},{"de":"Könnten Sie mich bitte mit Frau Becker verbinden?","fa":"ممکن است لطفاً مرا به خانم بکر وصل کنید؟","note":"«jemanden mit jemandem verbinden» یعنی تماس را به کسی وصل کردن."},{"de":"Entschuldigung, die Verbindung ist sehr schlecht. Können Sie das wiederholen?","fa":"ببخشید، خط خیلی بد است. می‌توانید تکرار کنید؟","note":"وقتی صدا قطع و وصل می‌شود؛ «die Verbindung» یعنی ارتباط یا خط تلفن."},{"de":"Kann ich eine Nachricht für ihn hinterlassen?","fa":"می‌توانم برایش پیغام بگذارم؟","note":"«eine Nachricht hinterlassen» وقتی شخص موردنظر در دسترس نیست."},{"de":"Ich melde mich dann morgen noch einmal bei Ihnen.","fa":"پس فردا دوباره با شما تماس می‌گیرم.","note":"«sich bei jemandem melden» یعنی تماس گرفتن یا خبر دادن؛ بسیار پرکاربرد."}]},{"day":6,"theme":"Termine vereinbaren und absagen","theme_fa":"وقت گرفتن و لغو قرار","s":[{"de":"Ich würde gern einen Termin für nächste Woche vereinbaren.","fa":"مایلم برای هفته‌ی آینده یک وقت بگیرم.","note":"«einen Termin vereinbaren» عبارت استاندارد برای وقت گرفتن است."},{"de":"Passt es Ihnen am Dienstag um zehn Uhr?","fa":"سه‌شنبه ساعت ده برایتان مناسب است؟","note":"«passen» با Dativ می‌آید؛ غیررسمی: «Passt es dir?»"},{"de":"Leider muss ich unseren Termin morgen absagen.","fa":"متأسفانه باید قرار فردایمان را لغو کنم.","note":"«absagen» یعنی لغو کردن؛ بهتر است دلیلی کوتاه هم اضافه کنید."},{"de":"Wäre es möglich, den Termin auf Donnerstag zu verschieben?","fa":"امکان دارد وقت را به پنج‌شنبه موکول کنیم؟","note":"«verschieben auf + Akkusativ» یعنی عقب انداختن به زمانی دیگر."},{"de":"Donnerstag geht bei mir leider nicht, aber Freitag wäre super.","fa":"پنج‌شنبه متأسفانه برایم نمی‌شود، ولی جمعه عالی است.","note":"«geht bei mir (nicht)» در گفتار روزمره برای هماهنگی زمان بسیار رایج است."}]},{"day":7,"theme":"Beim Arzt","theme_fa":"پیش پزشک","s":[{"de":"Ich habe seit drei Tagen starke Halsschmerzen.","fa":"سه روز است که گلودرد شدیدی دارم.","note":"«seit» همراه با زمان حال برای مشکلی که هنوز ادامه دارد."},{"de":"Mir ist seit heute Morgen ständig schwindelig.","fa":"از امروز صبح مدام سرم گیج می‌رود.","note":"«Mir ist schwindelig/übel» با Dativ ساخته می‌شود، نه با «Ich bin»."},{"de":"Können Sie mich bitte krankschreiben?","fa":"می‌توانید لطفاً برایم گواهی استعلاجی بنویسید؟","note":"«krankschreiben» یعنی صدور گواهی بیماری برای محل کار."},{"de":"Muss ich das Medikament vor oder nach dem Essen nehmen?","fa":"باید دارو را قبل از غذا بخورم یا بعد از غذا؟","note":"در آلمانی دارو را «nehmen» می‌کنند، نه «essen» یا «trinken»."},{"de":"Ich bin gegen Penicillin allergisch.","fa":"به پنی‌سیلین حساسیت دارم.","note":"«allergisch gegen + Akkusativ»؛ حتماً پیش از نسخه به پزشک بگویید."}]},{"day":8,"theme":"In der Apotheke","theme_fa":"در داروخانه","s":[{"de":"Ich hätte gern etwas gegen Kopfschmerzen.","fa":"چیزی برای سردرد می‌خواستم.","note":"«etwas gegen + بیماری» عبارت رایج در داروخانه است."},{"de":"Ist dieses Medikament rezeptpflichtig?","fa":"این دارو نسخه لازم دارد؟","note":"«rezeptpflichtig» یعنی نیازمند نسخه؛ «rezeptfrei» یعنی بدون نسخه."},{"de":"Haben Sie das auch als Generikum? Das wäre günstiger.","fa":"این را به‌صورت ژنریک هم دارید؟ ارزان‌تر می‌شد.","note":"Generikum داروی ژنریک با همان ماده‌ی مؤثر و قیمت کمتر است."},{"de":"Wie oft am Tag soll ich die Tabletten einnehmen?","fa":"روزی چند بار باید قرص‌ها را بخورم؟","note":"«einnehmen» برای مصرف دارو کمی رسمی‌تر از «nehmen» است."},{"de":"Können Sie mir das bis morgen bestellen?","fa":"می‌توانید این را تا فردا برایم سفارش بدهید؟","note":"داروخانه‌های آلمان داروی ناموجود را معمولاً تا روز بعد تهیه می‌کنند."}]},{"day":9,"theme":"Auf dem Amt (Bürgeramt, Ausländerbehörde)","theme_fa":"در اداره (اداره‌ی ثبت سکونت، اداره‌ی اتباع خارجی)","s":[{"de":"Ich möchte mich hier anmelden, ich bin vor Kurzem umgezogen.","fa":"می‌خواهم اینجا آدرسم را ثبت کنم، به‌تازگی اسباب‌کشی کرده‌ام.","note":"«sich anmelden» یعنی ثبت آدرس در Bürgeramt؛ معمولاً ظرف دو هفته لازم است."},{"de":"Welche Unterlagen muss ich zum Termin mitbringen?","fa":"چه مدارکی باید برای وقت ملاقات همراه بیاورم؟","note":"سؤالی کلیدی پیش از هر وقت اداری؛ «Unterlagen» یعنی مدارک."},{"de":"Mein Aufenthaltstitel läuft nächsten Monat ab.","fa":"اجازه‌ی اقامتم ماه آینده تمام می‌شود.","note":"«ablaufen» یعنی منقضی شدن؛ برای تمدید زود اقدام کنید."},{"de":"Könnten Sie mir bitte erklären, wie ich dieses Formular ausfülle?","fa":"ممکن است لطفاً توضیح دهید این فرم را چطور پر کنم؟","note":"«ein Formular ausfüllen» یعنی فرم پر کردن؛ در سؤال غیرمستقیم فعل به آخر می‌رود."},{"de":"Wie lange dauert die Bearbeitung ungefähr?","fa":"رسیدگی به پرونده تقریباً چقدر طول می‌کشد؟","note":"«die Bearbeitung» یعنی رسیدگی به درخواست؛ واژه‌ای بسیار اداری."}]},{"day":10,"theme":"Bank und Konto","theme_fa":"بانک و حساب بانکی","s":[{"de":"Ich möchte gern ein Girokonto eröffnen.","fa":"می‌خواهم یک حساب جاری باز کنم.","note":"«ein Konto eröffnen» یعنی حساب باز کردن؛ «ein Konto kündigen» یعنی بستن حساب."},{"de":"Fallen für das Konto monatliche Gebühren an?","fa":"آیا این حساب کارمزد ماهانه دارد؟","note":"«Gebühren fallen an» یعنی هزینه تعلق می‌گیرد؛ عبارت رسمی و رایج بانکی."},{"de":"Meine Karte ist gestern verloren gegangen, ich muss sie sperren lassen.","fa":"کارتم دیروز گم شد، باید آن را مسدود کنم.","note":"«sperren lassen» یعنی مسدود کردن کارت توسط بانک؛ شماره‌ی اضطراری: 116 116."},{"de":"Wie lange dauert eine Überweisung ins Ausland?","fa":"انتقال پول به خارج از کشور چقدر طول می‌کشد؟","note":"«die Überweisung» یعنی انتقال بانکی یا حواله."},{"de":"Ich habe eine Abbuchung auf meinem Kontoauszug, die ich nicht verstehe.","fa":"در صورت‌حسابم برداشتی هست که از آن سر درنمی‌آورم.","note":"«Kontoauszug» یعنی صورت‌حساب؛ «Abbuchung» یعنی برداشت از حساب."}]},{"day":11,"theme":"Wohnungssuche","theme_fa":"جست‌وجوی خانه","s":[{"de":"Ist die Wohnung noch frei?","fa":"آپارتمان هنوز خالی است؟","note":"اولین سؤال هنگام تماس برای آگهی؛ «frei» یعنی هنوز اجاره داده نشده."},{"de":"Wie hoch ist die Warmmiete inklusive Nebenkosten?","fa":"اجاره‌ی کامل با هزینه‌های جانبی چقدر است؟","note":"Kaltmiete بدون هزینه‌های جانبی است و Warmmiete با گرمایش و هزینه‌های جانبی."},{"de":"Wann könnte ich mir die Wohnung ansehen?","fa":"کی می‌توانم برای دیدن خانه بیایم؟","note":"«sich etwas ansehen» یعنی دیدن و بازدید کردن؛ بازدید خانه: Besichtigung."},{"de":"Ich interessiere mich sehr für die Wohnung und könnte sofort einziehen.","fa":"خیلی به این آپارتمان علاقه دارم و می‌توانم فوراً نقل مکان کنم.","note":"«sich interessieren für»؛ آمادگی برای نقل مکان فوری شانس شما را بیشتر می‌کند."},{"de":"Muss ich eine Kaution hinterlegen, und wenn ja, wie hoch?","fa":"باید ودیعه بگذارم؟ اگر بله، چقدر؟","note":"«Kaution» یعنی ودیعه؛ حداکثر سه برابر اجاره‌ی بدون هزینه‌ها (Kaltmiete) است."}]},{"day":12,"theme":"Mit dem Vermieter / den Nachbarn sprechen","theme_fa":"صحبت با صاحب‌خانه و همسایه‌ها","s":[{"de":"Die Heizung in meiner Wohnung funktioniert seit gestern nicht mehr.","fa":"شوفاژ خانه‌ام از دیروز دیگر کار نمی‌کند.","note":"گزارش خرابی به صاحب‌خانه؛ بهتر است کتبی هم اطلاع دهید."},{"de":"Könnten Sie bitte jemanden vorbeischicken, der sich das ansieht?","fa":"ممکن است لطفاً کسی را بفرستید که نگاهی به آن بیندازد؟","note":"«vorbeischicken» یعنی فرستادن کسی برای سر زدن؛ بعد از آن جمله‌ی موصولی آمده است."},{"de":"Entschuldigen Sie, könnten Sie die Musik abends etwas leiser machen?","fa":"ببخشید، ممکن است شب‌ها صدای موسیقی را کمی کم کنید؟","note":"ساعت سکوت (Ruhezeit) در آلمان معمولاً از ۲۲ تا ۶ صبح است."},{"de":"Ich bekomme am Samstag ein Paket. Könnten Sie es eventuell für mich annehmen?","fa":"شنبه یک بسته برایم می‌آید. ممکن است آن را برایم تحویل بگیرید؟","note":"درخواستی رایج بین همسایه‌ها؛ «eventuell» درخواست را نرم‌تر می‌کند."},{"de":"Wir feiern am Freitag eine kleine Party. Ich hoffe, das stört Sie nicht.","fa":"جمعه یک مهمانی کوچک داریم. امیدوارم مزاحمتان نشود.","note":"خبر دادن از قبل به همسایه‌ها در آلمان نشانه‌ی ادب است."}]},{"day":13,"theme":"Im Restaurant","theme_fa":"در رستوران","s":[{"de":"Haben Sie einen Tisch für zwei Personen frei?","fa":"یک میز خالی برای دو نفر دارید؟","note":"هنگام ورود به رستوران بدون رزرو قبلی."},{"de":"Was können Sie uns heute empfehlen?","fa":"امروز چه چیزی به ما پیشنهاد می‌کنید؟","note":"«empfehlen» یعنی توصیه کردن؛ گارسون‌ها معمولاً غذای روز را معرفی می‌کنند."},{"de":"Ist in dem Gericht Schweinefleisch?","fa":"در این غذا گوشت خوک هست؟","note":"سؤالی مهم برای کسی که گوشت خوک نمی‌خورد؛ «das Gericht» یعنی غذا یا خوراک."},{"de":"Wir möchten bitte zahlen, getrennt bitte.","fa":"لطفاً می‌خواهیم حساب کنیم، جداجدا.","note":"«getrennt» یعنی جدا و «zusammen» یعنی با هم؛ گارسون معمولاً این را می‌پرسد."},{"de":"Stimmt so, vielen Dank!","fa":"بقیه‌اش مال خودتان، خیلی ممنون!","note":"هنگام پرداخت یعنی باقی پول انعام است؛ انعام معمول حدود ۵ تا ۱۰ درصد است."}]},{"day":14,"theme":"Einkaufen und Reklamieren","theme_fa":"خرید و شکایت از کالا","s":[{"de":"Haben Sie diese Jacke auch eine Nummer größer?","fa":"این کاپشن را یک سایز بزرگ‌تر هم دارید؟","note":"«eine Nummer größer/kleiner» برای سایز لباس و کفش به‌کار می‌رود."},{"de":"Kann ich das umtauschen, falls es nicht passt?","fa":"اگر اندازه نبود، می‌توانم عوضش کنم؟","note":"«umtauschen» یعنی تعویض کالا؛ «zurückgeben» یعنی پس دادن آن."},{"de":"Ich habe den Staubsauger letzte Woche gekauft, und er funktioniert schon nicht mehr.","fa":"جاروبرقی را هفته‌ی پیش خریدم و همین حالا دیگر کار نمی‌کند.","note":"شروع شکایت از کالا؛ رسید خرید (Kassenbon) را همراه داشته باشید."},{"de":"Ich hätte gern mein Geld zurück.","fa":"می‌خواهم پولم را پس بگیرم.","note":"محکم ولی مؤدبانه؛ گاهی فروشگاه به‌جای پول کارت اعتبار خرید (Gutschein) می‌دهد."},{"de":"Das Gerät hat doch noch Garantie, oder?","fa":"این دستگاه که هنوز گارانتی دارد، نه؟","note":"«doch» نشان می‌دهد گوینده انتظار تأیید دارد؛ ضمانت قانونی (Gewährleistung) دو سال است."}]},{"day":15,"theme":"Bahn und Reisen","theme_fa":"قطار و سفر","s":[{"de":"Muss ich in Frankfurt umsteigen?","fa":"باید در فرانکفورت قطار عوض کنم؟","note":"«umsteigen» یعنی عوض کردن وسیله‌ی نقلیه؛ فعلی جداشدنی است."},{"de":"Der Zug hat leider zwanzig Minuten Verspätung.","fa":"قطار متأسفانه بیست دقیقه تأخیر دارد.","note":"«Verspätung haben» یعنی تأخیر داشتن؛ جمله‌ای که در آلمان زیاد می‌شنوید!"},{"de":"Ist dieser Platz noch frei?","fa":"این صندلی هنوز خالی است؟","note":"قبل از نشستن در قطار یا اتوبوس؛ پاسخ: «Ja, bitte» یا «Nein, besetzt»."},{"de":"Ich habe meinen Anschluss verpasst. Was kann ich jetzt machen?","fa":"قطار بعدی‌ام را از دست دادم. حالا چه کار کنم؟","note":"«der Anschluss» یعنی قطار یا اتوبوس رابط؛ در این حالت به مرکز خدمات مسافر بروید."},{"de":"Gilt mein Ticket auch für die S-Bahn?","fa":"بلیتم برای اس‌بان هم معتبر است؟","note":"«gelten für» یعنی معتبر بودن برای چیزی؛ درباره‌ی بلیت بسیار کاربردی است."}]},{"day":16,"theme":"Wegbeschreibung","theme_fa":"آدرس پرسیدن و آدرس دادن","s":[{"de":"Entschuldigung, wie komme ich am besten zum Hauptbahnhof?","fa":"ببخشید، بهترین راه برای رسیدن به ایستگاه مرکزی قطار چیست؟","note":"«Wie komme ich zu/nach ...?» رایج‌ترین شکل پرسیدن آدرس است."},{"de":"Gehen Sie hier geradeaus und dann die zweite Straße links.","fa":"از اینجا مستقیم بروید و بعد خیابان دوم سمت چپ.","note":"امر رسمی با Sie؛ «die zweite Straße links» بدون حرف اضافه می‌آید."},{"de":"Ist das weit von hier, oder kann man zu Fuß gehen?","fa":"از اینجا دور است یا می‌شود پیاده رفت؟","note":"«zu Fuß gehen» یعنی پیاده رفتن."},{"de":"Sie können es gar nicht verfehlen, es ist direkt gegenüber der Post.","fa":"امکان ندارد پیدایش نکنید، درست روبه‌روی اداره‌ی پست است.","note":"«gegenüber» با Dativ می‌آید؛ «verfehlen» یعنی پیدا نکردن یا از دست دادن."},{"de":"Tut mir leid, ich bin auch nicht von hier.","fa":"متأسفم، من هم اهل اینجا نیستم.","note":"پاسخی طبیعی وقتی آدرس را نمی‌دانید."}]},{"day":17,"theme":"Sich vorstellen","theme_fa":"معرفی خود","s":[{"de":"Darf ich mich kurz vorstellen? Mein Name ist Sara Karimi.","fa":"اجازه می‌دهید خودم را کوتاه معرفی کنم؟ اسمم سارا کریمی است.","note":"شروعی رسمی در جلسه، کلاس یا مصاحبه."},{"de":"Ich komme ursprünglich aus dem Iran und lebe seit zwei Jahren in Leipzig.","fa":"اصالتاً اهل ایران هستم و دو سال است در لایپزیگ زندگی می‌کنم.","note":"«aus dem Iran» با حرف تعریف می‌آید؛ «ursprünglich» یعنی در اصل."},{"de":"Ich habe Maschinenbau studiert und arbeite jetzt als Ingenieurin.","fa":"مهندسی مکانیک خوانده‌ام و الان به‌عنوان مهندس کار می‌کنم.","note":"«als + شغل» بدون حرف تعریف می‌آید؛ برای مرد: Ingenieur."},{"de":"In meiner Freizeit lese ich gern und gehe oft wandern.","fa":"در وقت آزادم دوست دارم کتاب بخوانم و اغلب به پیاده‌روی در طبیعت می‌روم.","note":"«gern» همراه فعل برای بیان علاقه؛ «wandern gehen» یعنی طبیعت‌گردی پیاده."},{"de":"Freut mich, Sie kennenzulernen!","fa":"از آشنایی با شما خوشوقتم!","note":"پاسخ استاندارد هنگام آشنایی؛ غیررسمی: «Schön, dich kennenzulernen!»"}]},{"day":18,"theme":"Gefühle ausdrücken","theme_fa":"بیان احساسات","s":[{"de":"Ich freue mich riesig auf die Reise nächste Woche.","fa":"برای سفر هفته‌ی آینده خیلی ذوق دارم.","note":"«sich freuen auf» برای آینده و «sich freuen über» برای چیزی که اتفاق افتاده است."},{"de":"Ehrlich gesagt bin ich ziemlich enttäuscht von dem Ergebnis.","fa":"راستش از نتیجه خیلی ناامید شده‌ام.","note":"«enttäuscht von + Dativ» یعنی ناامید از چیزی یا کسی."},{"de":"Es macht mich wahnsinnig, wenn die Leute ständig zu spät kommen.","fa":"وقتی آدم‌ها مدام دیر می‌آیند، کلافه می‌شوم.","note":"محاوره‌ای؛ «jemanden wahnsinnig machen» یعنی کسی را دیوانه یا کلافه کردن."},{"de":"Ich habe ein bisschen Angst vor der Prüfung.","fa":"کمی از امتحان می‌ترسم.","note":"«Angst haben vor + Dativ»؛ «ein bisschen» احساس را ملایم‌تر می‌کند."},{"de":"Ich bin total erleichtert, dass alles gut gegangen ist.","fa":"خیلی خیالم راحت شد که همه چیز خوب پیش رفت.","note":"«erleichtert sein» یعنی خیال کسی راحت شدن؛ «gut gehen» در Perfekt با sein می‌آید."}]},{"day":19,"theme":"Sich entschuldigen","theme_fa":"عذرخواهی کردن","s":[{"de":"Es tut mir wirklich leid, dass ich mich so spät melde.","fa":"واقعاً متأسفم که این‌قدر دیر خبر می‌دهم.","note":"شروع رایج ایمیل وقتی دیر جواب می‌دهید."},{"de":"Entschuldigen Sie bitte die Verspätung, der Bus kam nicht.","fa":"لطفاً تأخیرم را ببخشید، اتوبوس نیامد.","note":"«Entschuldigen Sie + Akkusativ» برای عذرخواهی رسمی بابت چیزی."},{"de":"Das war nicht so gemeint, bitte sei mir nicht böse.","fa":"منظورم این نبود، لطفاً از من دلخور نشو.","note":"غیررسمی؛ «jemandem böse sein» یعنی از کسی دلخور بودن."},{"de":"Ich muss mich bei Ihnen für das Missverständnis entschuldigen.","fa":"باید بابت این سوءتفاهم از شما عذرخواهی کنم.","note":"ساختار کامل و رسمی: «sich bei jemandem für etwas entschuldigen»."},{"de":"Kein Problem, das kann doch jedem mal passieren.","fa":"مشکلی نیست، ممکن است برای هر کسی پیش بیاید.","note":"پاسخی مهربانانه به عذرخواهی دیگران."}]},{"day":20,"theme":"Danken und Komplimente","theme_fa":"تشکر و تعریف کردن","s":[{"de":"Vielen Dank für Ihre Hilfe, das war wirklich sehr nett von Ihnen.","fa":"خیلی ممنون از کمکتان، واقعاً لطف کردید.","note":"«nett von Ihnen» یعنی لطف شما؛ تشکری گرم و رسمی."},{"de":"Ich weiß das wirklich zu schätzen.","fa":"واقعاً قدرش را می‌دانم.","note":"«etwas zu schätzen wissen» یعنی قدردان چیزی بودن؛ صمیمانه و کمی رسمی."},{"de":"Das Essen war echt lecker, du musst mir unbedingt das Rezept geben!","fa":"غذا واقعاً خوشمزه بود، حتماً باید دستورش را به من بدهی!","note":"تعریف از غذا در مهمانی؛ «echt» محاوره‌ای و به معنای «واقعاً» است."},{"de":"Ihr Vortrag war sehr interessant und gut strukturiert.","fa":"ارائه‌ی شما خیلی جالب و منظم بود.","note":"تعریفی حرفه‌ای در دانشگاه یا محل کار."},{"de":"Gern geschehen, das habe ich doch gern gemacht.","fa":"خواهش می‌کنم، با کمال میل این کار را کردم.","note":"پاسخ به تشکر؛ کوتاه‌تر: «Gern geschehen!» یا «Keine Ursache!»"}]},{"day":21,"theme":"Ratschläge geben","theme_fa":"توصیه و راهنمایی کردن","s":[{"de":"An deiner Stelle würde ich sofort mit dem Chef sprechen.","fa":"من جای تو بودم، فوراً با رئیس صحبت می‌کردم.","note":"«An deiner/Ihrer Stelle würde ich ...» رایج‌ترین ساختار برای توصیه است."},{"de":"Du solltest dir vielleicht mal eine Pause gönnen.","fa":"شاید بهتر باشد کمی به خودت استراحت بدهی.","note":"«sollte» همراه «vielleicht» توصیه را نرم می‌کند؛ «sich etwas gönnen» یعنی چیزی را از خود دریغ نکردن."},{"de":"Es wäre sinnvoll, nicht bis zum letzten Tag zu warten.","fa":"عاقلانه است که تا روز آخر صبر نکنید.","note":"«Es wäre sinnvoll, ... zu» توصیه‌ای غیرمستقیم و رسمی است."},{"de":"Ich würde Ihnen raten, alle Belege gut aufzubewahren.","fa":"به شما توصیه می‌کنم همه‌ی رسیدها را خوب نگه دارید.","note":"«jemandem raten, ... zu» با Dativ؛ مثلاً برای اظهارنامه‌ی مالیاتی."},{"de":"Hast du schon mal darüber nachgedacht, einen Sprachkurs zu machen?","fa":"تا حالا به گذراندن یک دوره‌ی زبان فکر کرده‌ای؟","note":"توصیه به‌شکل سؤال؛ غیرمستقیم و دوستانه."}]},{"day":22,"theme":"Vorschläge machen","theme_fa":"پیشنهاد دادن","s":[{"de":"Wie wäre es, wenn wir uns am Samstag treffen?","fa":"چطور است شنبه همدیگر را ببینیم؟","note":"«Wie wäre es, wenn ...?» پیشنهادی مؤدبانه و غیرمستقیم است."},{"de":"Lass uns doch einfach eine Pizza bestellen.","fa":"بیا خیلی ساده پیتزا سفارش بدهیم.","note":"«Lass uns ...» غیررسمی است؛ خطاب به چند نفر: «Lasst uns ...»."},{"de":"Ich schlage vor, dass wir das Thema in der nächsten Sitzung besprechen.","fa":"پیشنهاد می‌کنم این موضوع را در جلسه‌ی بعدی بررسی کنیم.","note":"«vorschlagen» رسمی و مناسب جلسات کاری است."},{"de":"Was hältst du davon, wenn wir mal ins Kino gehen?","fa":"نظرت چیست که یک بار برویم سینما؟","note":"«Was hältst du davon?» هم پیشنهاد است و هم نظر طرف را می‌پرسد."},{"de":"Wir könnten ja auch mit dem Fahrrad fahren, das Wetter ist doch schön.","fa":"می‌توانیم با دوچرخه هم برویم، هوا که خوب است.","note":"«könnten» همراه «ja auch» پیشنهاد جایگزین را ملایم مطرح می‌کند."}]},{"day":23,"theme":"Einladen und reagieren","theme_fa":"دعوت کردن و پاسخ به دعوت","s":[{"de":"Ich habe am Samstag Geburtstag und würde dich gern einladen.","fa":"شنبه تولدم است و دوست دارم دعوتت کنم.","note":"دعوت دوستانه؛ «Geburtstag haben» یعنی روز تولد کسی بودن."},{"de":"Hast du Lust, am Wochenende mit uns grillen zu gehen?","fa":"حوصله داری آخر هفته با ما برای کباب درست کردن بیرون بیایی؟","note":"«Lust haben, ... zu» یعنی تمایل داشتن؛ دعوتی غیررسمی."},{"de":"Vielen Dank für die Einladung, ich komme sehr gern!","fa":"خیلی ممنون از دعوت، با کمال میل می‌آیم!","note":"پذیرش گرم دعوت به‌صورت شفاهی یا پیامی."},{"de":"Das ist echt lieb von dir, aber da kann ich leider nicht.","fa":"واقعاً لطف داری، ولی متأسفانه آن موقع نمی‌توانم.","note":"رد مؤدبانه‌ی دعوت؛ بهتر است دلیل یا زمان دیگری پیشنهاد کنید."},{"de":"Soll ich etwas mitbringen, vielleicht einen Salat oder Getränke?","fa":"چیزی بیاورم؟ مثلاً سالاد یا نوشیدنی؟","note":"در مهمانی‌های آلمانی آوردن چیزی با خود بسیار رایج است."}]},{"day":24,"theme":"Überraschung und Zweifel ausdrücken","theme_fa":"بیان تعجب و تردید","s":[{"de":"Echt jetzt? Das hätte ich nie gedacht!","fa":"جدی؟ هیچ‌وقت فکرش را نمی‌کردم!","note":"محاوره‌ای؛ «Das hätte ich nie gedacht» با Konjunktiv II گذشته ساخته شده."},{"de":"Das kann doch nicht wahr sein!","fa":"باورم نمی‌شود!","note":"برای تعجب منفی یا عصبانیت؛ «doch» تأکید را بیشتر می‌کند."},{"de":"Ich bin mir nicht ganz sicher, ob das stimmt.","fa":"کاملاً مطمئن نیستم که این درست باشد.","note":"«sich sicher sein, ob ...»؛ «mir» ضمیر انعکاسی در حالت Dativ است."},{"de":"Ich habe da so meine Zweifel.","fa":"راستش در این مورد تردیدهایی دارم.","note":"«so meine Zweifel» لحنی محتاطانه و کمی کنایه‌آمیز دارد."},{"de":"Das überrascht mich jetzt ehrlich gesagt ein bisschen.","fa":"راستش این کمی غافلگیرم می‌کند.","note":"تعجبی مؤدبانه و رسمی، مثلاً در جلسه."}]},{"day":25,"theme":"Nachfragen, wenn man nicht versteht","theme_fa":"دوباره پرسیدن وقتی متوجه نمی‌شویم","s":[{"de":"Entschuldigung, könnten Sie das bitte etwas langsamer sagen?","fa":"ببخشید، ممکن است لطفاً کمی آهسته‌تر بگویید؟","note":"کاملاً عادی و مؤدبانه است؛ آلمانی‌ها معمولاً با کمال میل آهسته‌تر حرف می‌زنند."},{"de":"Was meinen Sie genau mit „zeitnah“?","fa":"منظورتان دقیقاً از «zeitnah» چیست؟","note":"برای پرسیدن معنی یک واژه؛ «zeitnah» یعنی به‌زودی و در ایمیل‌ها رایج است."},{"de":"Habe ich Sie richtig verstanden, dass der Kurs ausfällt?","fa":"درست متوجه شدم که کلاس برگزار نمی‌شود؟","note":"برای اطمینان از فهم درست؛ «ausfallen» یعنی لغو شدن."},{"de":"Wie bitte? Ich habe Sie akustisch nicht verstanden.","fa":"ببخشید؟ صدایتان را درست نشنیدم.","note":"«akustisch nicht verstanden» یعنی مشکل از شنیدن است، نه از زبان."},{"de":"Könnten Sie mir das vielleicht an einem Beispiel erklären?","fa":"ممکن است با یک مثال برایم توضیح دهید؟","note":"در کلاس، دانشگاه یا محل کار، وقتی توضیح خیلی انتزاعی است."}]},{"day":26,"theme":"Meinung sagen","theme_fa":"بیان نظر","s":[{"de":"Ich bin der Meinung, dass Homeoffice viele Vorteile bietet.","fa":"نظرم این است که دورکاری مزایای زیادی دارد.","note":"«der Meinung sein, dass» رسمی‌تر از «Ich finde» و مناسب نوشتار و بحث است."},{"de":"Für mich persönlich ist Zeit wichtiger als Geld.","fa":"برای من شخصاً وقت از پول مهم‌تر است.","note":"«für mich persönlich» تأکید می‌کند که این نظری شخصی است."},{"de":"Ich habe den Eindruck, dass sich viele Leute zu wenig bewegen.","fa":"احساس می‌کنم خیلی از آدم‌ها تحرک بسیار کمی دارند.","note":"«den Eindruck haben, dass» برای نظری که بر مشاهده تکیه دارد."},{"de":"Meines Erachtens wurde das Problem bisher unterschätzt.","fa":"به عقیده‌ی من این مشکل تا حالا دست‌کم گرفته شده است.","note":"«meines Erachtens» بسیار رسمی است و در مقاله و نامه‌ی رسمی می‌آید (مخفف: m. E.)."},{"de":"Ich weiß nicht, aber irgendwie finde ich das übertrieben.","fa":"نمی‌دانم، ولی یک جورهایی به نظرم اغراق‌آمیز است.","note":"محاوره‌ای؛ «irgendwie» نظر را ملایم و نامطمئن می‌کند."}]},{"day":27,"theme":"Zustimmen und widersprechen","theme_fa":"موافقت و مخالفت","s":[{"de":"Genau das wollte ich auch gerade sagen!","fa":"دقیقاً همین را می‌خواستم بگویم!","note":"موافقتی پرشور و غیررسمی در گفت‌وگو."},{"de":"Da hast du völlig recht.","fa":"کاملاً حق با توست.","note":"«recht haben» یعنی حق داشتن؛ رسمی: «Da haben Sie völlig recht.»"},{"de":"Ich sehe das ein bisschen anders.","fa":"من این موضوع را کمی متفاوت می‌بینم.","note":"مخالفتی بسیار ملایم و دیپلماتیک؛ بعد از آن دلیل خود را بگویید."},{"de":"Das mag sein, aber man darf nicht vergessen, dass die Mieten steigen.","fa":"شاید این‌طور باشد، ولی نباید فراموش کرد که اجاره‌ها بالا می‌روند.","note":"«Das mag sein, aber ...» یعنی پذیرش بخشی از حرف و سپس مخالفت."},{"de":"Da bin ich mir nicht so sicher, ehrlich gesagt.","fa":"راستش در این مورد چندان مطمئن نیستم.","note":"مخالفتی غیرمستقیم به‌جای «Das ist falsch»؛ مؤدبانه‌تر است."}]},{"day":28,"theme":"Höfliche Bitten","theme_fa":"درخواست‌های مؤدبانه","s":[{"de":"Dürfte ich Sie kurz stören?","fa":"اجازه هست یک لحظه مزاحمتان شوم؟","note":"«dürfte» بسیار مؤدبانه است؛ برای شروع صحبت با همکار یا استاد."},{"de":"Wären Sie so nett, mir die Datei noch einmal zu schicken?","fa":"لطف می‌کنید فایل را دوباره برایم بفرستید؟","note":"«Wären Sie so nett, ... zu» درخواستی گرم و مؤدبانه است."},{"de":"Ich wäre Ihnen sehr dankbar, wenn Sie mir bald antworten könnten.","fa":"بسیار ممنون می‌شوم اگر بتوانید به‌زودی پاسخ دهید.","note":"پایان رایج ایمیل رسمی؛ «jemandem dankbar sein» با Dativ می‌آید."},{"de":"Machst du mir bitte kurz die Tür auf?","fa":"لطفاً یک لحظه در را برایم باز می‌کنی؟","note":"غیررسمی؛ سؤال در زمان حال، درخواستی روزمره و طبیعی است."},{"de":"Hätten Sie vielleicht einen Moment Zeit für mich?","fa":"شاید یک لحظه برای من وقت داشته باشید؟","note":"«Hätten Sie ...?» با Konjunktiv II درخواست را نرم‌تر می‌کند."}]},{"day":29,"theme":"Small Talk","theme_fa":"گپ کوتاه و دوستانه","s":[{"de":"Wohnen Sie auch hier in der Gegend?","fa":"شما هم همین اطراف زندگی می‌کنید؟","note":"«in der Gegend» یعنی این اطراف؛ مناسب گپ با همسایه یا در مهمانی."},{"de":"Woher kennen Sie eigentlich die Gastgeber?","fa":"راستی میزبان‌ها را از کجا می‌شناسید؟","note":"سؤال رایج در مهمانی؛ «eigentlich» در سؤال یعنی «راستی»."},{"de":"Endlich wird es wieder wärmer, ich habe den Frühling so vermisst.","fa":"بالاخره هوا دوباره گرم‌تر می‌شود، دلم برای بهار خیلی تنگ شده بود.","note":"«vermissen» یعنی دلتنگ چیزی یا کسی بودن."},{"de":"Haben Sie den neuen Film schon gesehen?","fa":"فیلم جدید را دیده‌اید؟","note":"فیلم و فرهنگ موضوعی امن برای گپ زدن است."},{"de":"Viel los heute, was?","fa":"امروز خیلی شلوغ است، نه؟","note":"محاوره‌ای؛ «viel los» یعنی شلوغ؛ «was?» در پایان یعنی «نه؟»."}]},{"day":30,"theme":"Telefonieren","theme_fa":"تلفن زدن","s":[{"de":"Spreche ich mit Herrn Neumann?","fa":"با آقای نویمان صحبت می‌کنم؟","note":"برای اطمینان از اینکه با شخص درست صحبت می‌کنید؛ «Herrn» صرف Dativ است."},{"de":"Einen Moment bitte, ich verbinde Sie.","fa":"یک لحظه لطفاً، وصلتان می‌کنم.","note":"جمله‌ی رایج منشی‌ها؛ معنی‌اش را بدانید تا گوشی را قطع نکنید."},{"de":"Ich glaube, ich habe mich verwählt. Entschuldigen Sie die Störung.","fa":"فکر کنم اشتباه گرفته‌ام. ببخشید که مزاحم شدم.","note":"«sich verwählen» یعنی شماره را اشتباه گرفتن."},{"de":"Wann ist sie denn am besten zu erreichen?","fa":"بهترین زمان برای تماس با او کی است؟","note":"«erreichen» یعنی در دسترس بودن تلفنی؛ وقتی شخص موردنظر نیست."},{"de":"Ich rufe Sie gleich zurück, ich bin gerade unterwegs.","fa":"الان در راه هستم، زود به شما زنگ می‌زنم.","note":"«zurückrufen» یعنی دوباره تماس گرفتن؛ فعلی جداشدنی است."}]},{"day":31,"theme":"Termine vereinbaren und absagen","theme_fa":"وقت گرفتن و لغو قرار","s":[{"de":"Hätten Sie diese Woche noch einen Termin frei?","fa":"این هفته هنوز وقت خالی دارید؟","note":"برای مطب، آرایشگاه یا اداره؛ «einen Termin frei haben»."},{"de":"Ich möchte meinen Termin am Montag bestätigen.","fa":"می‌خواهم وقت دوشنبه‌ام را تأیید کنم.","note":"«bestätigen» یعنی تأیید کردن؛ برخی مطب‌ها تأیید قبلی می‌خواهند."},{"de":"Mir ist leider etwas dazwischengekommen.","fa":"متأسفانه برایم کاری پیش آمده.","note":"دلیلی رایج و مؤدبانه برای لغو قرار، بدون توضیح جزئیات."},{"de":"Lass uns doch einfach nächste Woche einen neuen Termin ausmachen.","fa":"بیا هفته‌ی بعد یک قرار جدید بگذاریم.","note":"«ausmachen» در محاوره همان «vereinbaren» است."},{"de":"Ich komme etwa zehn Minuten später, ich stehe im Stau.","fa":"حدود ده دقیقه دیرتر می‌رسم، در ترافیک گیر کرده‌ام.","note":"در آلمان خبر دادن تأخیر، حتی کوتاه، بسیار مهم است."}]},{"day":32,"theme":"Beim Arzt","theme_fa":"پیش پزشک","s":[{"de":"Ich hätte gern einen Termin, es ist ziemlich dringend.","fa":"یک وقت می‌خواستم، نسبتاً فوری است.","note":"هنگام تماس با مطب؛ «dringend» ممکن است باعث شود زودتر وقت بدهند."},{"de":"Die Schmerzen werden vor allem nachts schlimmer.","fa":"دردها به‌خصوص شب‌ها بدتر می‌شوند.","note":"توصیف دقیق زمان درد به تشخیص پزشک کمک می‌کند."},{"de":"Brauche ich eine Überweisung zum Facharzt?","fa":"برای رفتن به متخصص معرفی‌نامه لازم دارم؟","note":"«die Überweisung» اینجا یعنی ارجاع به پزشک متخصص."},{"de":"Ich nehme regelmäßig Medikamente gegen Bluthochdruck.","fa":"به‌طور منظم داروی فشار خون مصرف می‌کنم.","note":"داروهای مصرفی خود را همیشه به پزشک بگویید."},{"de":"Seit wann haben Sie diese Beschwerden?","fa":"از کی این ناراحتی‌ها را دارید؟","note":"سؤال رایج پزشک؛ «Beschwerden» یعنی علائم یا ناراحتی جسمی."}]},{"day":33,"theme":"In der Apotheke","theme_fa":"در داروخانه","s":[{"de":"Ich habe hier ein Rezept von meiner Ärztin.","fa":"اینجا نسخه‌ای از پزشکم دارم.","note":"«Rezept» در آلمانی هم نسخه‌ی پزشک است و هم دستور آشپزی."},{"de":"Gibt es dafür auch etwas Pflanzliches?","fa":"برای این مشکل داروی گیاهی هم هست؟","note":"«etwas Pflanzliches» صفتی است که به اسم تبدیل شده و یعنی چیزی گیاهی."},{"de":"Hat das Mittel Nebenwirkungen?","fa":"این دارو عوارض جانبی دارد؟","note":"«Nebenwirkungen» یعنی عوارض جانبی؛ «das Mittel» یعنی دارو."},{"de":"Kann ich das Medikament auch in der Schwangerschaft nehmen?","fa":"این دارو را در دوران بارداری هم می‌توانم مصرف کنم؟","note":"سؤال ایمنی مهم؛ داروساز موظف به راهنمایی شماست."},{"de":"Wie viel muss ich zuzahlen?","fa":"چقدر باید سهم خودم را بپردازم؟","note":"«zuzahlen» یعنی پرداخت سهم بیمار برای داروی نسخه‌ای، معمولاً ۵ تا ۱۰ یورو."}]},{"day":34,"theme":"Auf dem Amt (Bürgeramt, Ausländerbehörde)","theme_fa":"در اداره (اداره‌ی ثبت سکونت، اداره‌ی اتباع خارجی)","s":[{"de":"Ich möchte einen Antrag auf Verlängerung meiner Aufenthaltserlaubnis stellen.","fa":"می‌خواهم درخواست تمدید اجازه‌ی اقامتم را بدهم.","note":"«einen Antrag stellen auf + Akkusativ» یعنی درخواست رسمی دادن."},{"de":"Bin ich hier richtig, oder muss ich in ein anderes Zimmer?","fa":"اینجا را درست آمده‌ام یا باید به اتاق دیگری بروم؟","note":"«Bin ich hier richtig?» سؤالی بسیار کاربردی در ادارات بزرگ است."},{"de":"Leider fehlt noch eine Kopie meines Mietvertrags.","fa":"متأسفانه هنوز یک کپی از قرارداد اجاره‌ام کم است.","note":"در جمله با «fehlen» فاعل چیزی است که کم است."},{"de":"Kann ich die Unterlagen auch per E-Mail nachreichen?","fa":"می‌توانم مدارک را بعداً با ایمیل بفرستم؟","note":"«nachreichen» یعنی بعداً تحویل دادن مدارکِ ناقص."},{"de":"Ich bräuchte eine Bescheinigung für meinen Arbeitgeber.","fa":"به یک گواهی برای کارفرمایم نیاز داشتم.","note":"«bräuchte» (Konjunktiv II از brauchen) مؤدبانه‌تر از «brauche» است."}]},{"day":35,"theme":"Bank und Konto","theme_fa":"بانک و حساب بانکی","s":[{"de":"Ich möchte einen Dauerauftrag für meine Miete einrichten.","fa":"می‌خواهم برای اجاره‌ام یک دستور پرداخت دائمی تنظیم کنم.","note":"«Dauerauftrag» یعنی پرداخت خودکار ماهانه با مبلغ ثابت."},{"de":"Ich habe meine PIN vergessen. Was muss ich jetzt tun?","fa":"رمز کارتم را فراموش کرده‌ام. حالا چه کار باید بکنم؟","note":"«die PIN» مؤنث است؛ بانک معمولاً رمز جدید را با پست می‌فرستد."},{"de":"Der Geldautomat hat meine Karte eingezogen.","fa":"دستگاه خودپرداز کارتم را ضبط کرد.","note":"«einziehen» اینجا یعنی نگه داشتن کارت توسط دستگاه."},{"de":"Kann ich mein Konto auch online verwalten?","fa":"می‌توانم حسابم را آنلاین هم مدیریت کنم؟","note":"«verwalten» یعنی مدیریت کردن؛ بانکداری اینترنتی: Online-Banking."},{"de":"Wie hoch ist der Dispo bei diesem Konto?","fa":"سقف اضافه‌برداشت این حساب چقدر است؟","note":"«Dispo(kredit)» یعنی اضافه‌برداشت مجاز؛ بهره‌ی آن معمولاً بالاست."}]},{"day":36,"theme":"Wohnungssuche","theme_fa":"جست‌وجوی خانه","s":[{"de":"Ich habe Ihre Anzeige gelesen und interessiere mich für die Zweizimmerwohnung.","fa":"آگهی شما را خواندم و به آپارتمان دواتاقه علاقه دارم.","note":"شروع استاندارد ایمیل یا تماس با صاحب‌خانه."},{"de":"Sind Haustiere in der Wohnung erlaubt?","fa":"نگهداری حیوان خانگی در این آپارتمان مجاز است؟","note":"این را پیش از امضای قرارداد بپرسید."},{"de":"Ist die Küche schon eingebaut, oder muss ich eine eigene mitbringen?","fa":"آشپزخانه از قبل نصب شده یا باید خودم آشپزخانه بیاورم؟","note":"در آلمان بسیاری از خانه‌ها بدون کابینت و لوازم آشپزخانه (Einbauküche) اجاره داده می‌شوند."},{"de":"Ich kann eine Mietschuldenfreiheitsbescheinigung und Gehaltsnachweise vorlegen.","fa":"می‌توانم گواهی نداشتن بدهی اجاره و فیش‌های حقوقی ارائه دهم.","note":"«vorlegen» یعنی ارائه دادن مدرک؛ این مدارک شانس گرفتن خانه را بیشتر می‌کنند."},{"de":"Ab wann wäre die Wohnung bezugsfertig?","fa":"آپارتمان از چه زمانی آماده‌ی سکونت است؟","note":"«bezugsfertig» یعنی آماده‌ی نقل مکان؛ واژه‌ای رایج در آگهی‌ها."}]},{"day":37,"theme":"Mit dem Vermieter / den Nachbarn sprechen","theme_fa":"صحبت با صاحب‌خانه و همسایه‌ها","s":[{"de":"Im Badezimmer hat sich Schimmel gebildet.","fa":"در حمام کپک زده است.","note":"«Schimmel» یعنی کپک؛ مشکلی رایج که باید فوراً به صاحب‌خانه اطلاع داد."},{"de":"Ich möchte Sie darüber informieren, dass ich die Wohnung zum 31. März kündige.","fa":"می‌خواهم به اطلاعتان برسانم که قرارداد اجاره را برای ۳۱ مارس فسخ می‌کنم.","note":"فسخ اجاره باید کتبی و معمولاً سه ماه قبل باشد."},{"de":"Wann bekomme ich die Nebenkostenabrechnung?","fa":"صورت‌حساب هزینه‌های جانبی را کی دریافت می‌کنم؟","note":"این صورت‌حساب سالانه است و ممکن است بازپرداخت یا پرداخت اضافه داشته باشد."},{"de":"Hallo, ich bin neu hier eingezogen und wohne im dritten Stock.","fa":"سلام، تازه به اینجا آمده‌ام و در طبقه‌ی سوم زندگی می‌کنم.","note":"معرفی خود به همسایه‌ها رابطه‌ی خوبی می‌سازد."},{"de":"Könnten wir uns vielleicht absprechen, wer wann das Treppenhaus putzt?","fa":"ممکن است هماهنگ کنیم چه کسی و کی راه‌پله را تمیز کند؟","note":"«sich absprechen» یعنی با هم هماهنگ کردن؛ «Treppenhaus» یعنی راه‌پله."}]},{"day":38,"theme":"Im Restaurant","theme_fa":"در رستوران","s":[{"de":"Ich habe einen Tisch auf den Namen Rostami reserviert.","fa":"یک میز به نام رستمی رزرو کرده‌ام.","note":"«auf den Namen ...» یعنی به نامِ ...؛ هنگام ورود بگویید."},{"de":"Könnten wir bitte die Speisekarte haben?","fa":"ممکن است لطفاً منو را بیاورید؟","note":"«Speisekarte» منوی غذا و «Getränkekarte» منوی نوشیدنی است."},{"de":"Ich nehme die Gemüsepfanne, aber bitte ohne Zwiebeln.","fa":"من خوراک سبزیجات را می‌خواهم، ولی لطفاً بدون پیاز.","note":"«Ich nehme ...» رایج‌ترین شکل سفارش است؛ «ohne» برای حذف مواد."},{"de":"Entschuldigung, das Essen ist leider kalt.","fa":"ببخشید، غذا متأسفانه سرد است.","note":"شکایتی مؤدبانه؛ معمولاً غذا را عوض یا دوباره گرم می‌کنند."},{"de":"Kann man hier auch mit Karte zahlen?","fa":"اینجا با کارت هم می‌شود پرداخت کرد؟","note":"در آلمان هنوز برخی رستوران‌ها فقط پول نقد می‌پذیرند."}]},{"day":39,"theme":"Einkaufen und Reklamieren","theme_fa":"خرید و شکایت از کالا","s":[{"de":"Ich schaue mich nur ein bisschen um, danke.","fa":"فقط کمی نگاه می‌کنم، ممنون.","note":"پاسخ به فروشنده‌ای که می‌پرسد: «Kann ich Ihnen helfen?»"},{"de":"Wo finde ich die Umkleidekabinen?","fa":"اتاق پرو کجاست؟","note":"«Umkleidekabine» یعنی اتاق پرو؛ کوتاه‌تر: «Kabine»."},{"de":"Ist das im Angebot, oder gilt der volle Preis?","fa":"این در حراج است یا قیمت کامل حساب می‌شود؟","note":"«im Angebot» یعنی با تخفیف یا در حراج."},{"de":"Leider fehlt in der Verpackung ein Teil.","fa":"متأسفانه یک قطعه در بسته‌بندی نیست.","note":"شکایت از کالای ناقص؛ «fehlen» یعنی کم بودن یا نبودن."},{"de":"Ich möchte diese Bestellung reklamieren, die Ware ist beschädigt angekommen.","fa":"می‌خواهم از این سفارش شکایت کنم، کالا آسیب‌دیده رسیده است.","note":"«reklamieren» یعنی شکایت رسمی از کالا؛ از آسیب عکس بگیرید."}]},{"day":40,"theme":"Bahn und Reisen","theme_fa":"قطار و سفر","s":[{"de":"Von welchem Gleis fährt der Zug nach Hamburg ab?","fa":"قطار هامبورگ از کدام سکو حرکت می‌کند؟","note":"«das Gleis» یعنی سکو یا ریل؛ «abfahren» فعلی جداشدنی است."},{"de":"Ich hätte gern eine Hin- und Rückfahrkarte nach München.","fa":"یک بلیت رفت و برگشت به مونیخ می‌خواستم.","note":"«Hin- und Rückfahrt» یعنی رفت و برگشت؛ «einfach» یعنی فقط رفت."},{"de":"Kann ich mit diesem Ticket auch einen früheren Zug nehmen?","fa":"با این بلیت می‌توانم سوار قطار زودتری هم بشوم؟","note":"با بلیت ارزان (Sparpreis) معمولاً فقط همان قطار مشخص‌شده مجاز است."},{"de":"Der Zug fällt heute leider aus.","fa":"قطار امروز متأسفانه لغو شده است.","note":"«ausfallen» یعنی لغو شدن؛ در اعلام‌های ایستگاه زیاد شنیده می‌شود."},{"de":"Ich möchte eine Entschädigung für die Verspätung beantragen.","fa":"می‌خواهم برای تأخیر درخواست غرامت بدهم.","note":"از ۶۰ دقیقه تأخیر به بالا حق بازپرداخت بخشی از هزینه را دارید."}]},{"day":41,"theme":"Wegbeschreibung","theme_fa":"آدرس پرسیدن و آدرس دادن","s":[{"de":"Können Sie mir sagen, wo hier die nächste Apotheke ist?","fa":"می‌توانید به من بگویید نزدیک‌ترین داروخانه این اطراف کجاست؟","note":"سؤال غیرمستقیم: در جمله‌ی «wo ...» فعل به آخر می‌رود."},{"de":"Biegen Sie an der Ampel rechts ab.","fa":"سر چراغ راهنمایی به راست بپیچید.","note":"«abbiegen» یعنی پیچیدن و فعلی جداشدنی است؛ «an der Ampel» یعنی سر چراغ."},{"de":"Fahren Sie bis zur Endhaltestelle und steigen Sie dort aus.","fa":"تا ایستگاه آخر بروید و آنجا پیاده شوید.","note":"«aussteigen» یعنی پیاده شدن و «einsteigen» یعنی سوار شدن."},{"de":"Das sind ungefähr fünf Minuten zu Fuß.","fa":"حدود پنج دقیقه پیاده‌روی است.","note":"پاسخ معمول به سؤال «Ist das weit?»."},{"de":"Ich glaube, ich habe mich verlaufen. Können Sie mir helfen?","fa":"فکر کنم راه را گم کرده‌ام. می‌توانید کمکم کنید؟","note":"«sich verlaufen» برای پیاده و «sich verfahren» برای ماشین است."}]},{"day":42,"theme":"Sich vorstellen","theme_fa":"معرفی خود","s":[{"de":"Ich bin die Neue im Team und kümmere mich ab sofort um das Marketing.","fa":"من عضو جدید تیم هستم و از این به بعد مسئول بازاریابی‌ام.","note":"«die Neue/der Neue» یعنی تازه‌وارد؛ «sich kümmern um» یعنی مسئول چیزی بودن."},{"de":"Ich mache gerade meinen Master in Informatik an der TU Berlin.","fa":"الان دارم کارشناسی ارشد علوم کامپیوتر را در دانشگاه فنی برلین می‌خوانم.","note":"«den Master machen» محاوره‌ای و رایج است."},{"de":"Ich lerne seit drei Jahren Deutsch und möchte mich weiter verbessern.","fa":"سه سال است آلمانی یاد می‌گیرم و می‌خواهم باز هم پیشرفت کنم.","note":"«seit» با زمان حال؛ «sich verbessern» یعنی پیشرفت کردن."},{"de":"Zu meinen Stärken gehören Teamfähigkeit und Zuverlässigkeit.","fa":"کار تیمی و قابل‌اعتماد بودن از نقاط قوت من است.","note":"مناسب مصاحبه‌ی کاری؛ «gehören zu» یعنی جزء چیزی بودن."},{"de":"Sagen Sie ruhig du zu mir, das ist mir lieber.","fa":"راحت باشید و مرا «تو» خطاب کنید، این را ترجیح می‌دهم.","note":"پیشنهاد استفاده از «du»؛ معمولاً فرد مسن‌تر یا بالادست آن را پیشنهاد می‌دهد."}]},{"day":43,"theme":"Gefühle ausdrücken","theme_fa":"بیان احساسات","s":[{"de":"Ich bin so stolz auf dich!","fa":"خیلی به تو افتخار می‌کنم!","note":"«stolz sein auf + Akkusativ» یعنی به کسی یا چیزی افتخار کردن."},{"de":"In letzter Zeit fühle ich mich oft gestresst und müde.","fa":"این اواخر اغلب احساس استرس و خستگی می‌کنم.","note":"«in letzter Zeit» یعنی این اواخر؛ «sich fühlen» همراه صفت."},{"de":"Es ärgert mich, dass niemand Bescheid gesagt hat.","fa":"ناراحتم می‌کند که هیچ‌کس خبر نداد.","note":"«Es ärgert mich, dass ...»؛ «Bescheid sagen» یعنی خبر دادن."},{"de":"Ich vermisse meine Familie manchmal sehr.","fa":"گاهی خیلی دلم برای خانواده‌ام تنگ می‌شود.","note":"«vermissen» مفعول مستقیم می‌گیرد: «Ich vermisse dich.»"},{"de":"Ich bin gerade echt gut gelaunt, die Sonne scheint!","fa":"الان واقعاً سرحالم، آفتاب درآمده!","note":"«gut/schlecht gelaunt» یعنی خوش‌خلق یا بدخلق."}]},{"day":44,"theme":"Sich entschuldigen","theme_fa":"عذرخواهی کردن","s":[{"de":"Verzeihung, ich wollte Sie nicht unterbrechen.","fa":"ببخشید، نمی‌خواستم حرفتان را قطع کنم.","note":"«Verzeihung» رسمی است؛ «unterbrechen» یعنی حرف کسی را قطع کردن."},{"de":"Sorry, ich habe deine Nachricht total übersehen.","fa":"ببخشید، پیامت را اصلاً ندیدم.","note":"«Sorry» در محاوره رایج است؛ «übersehen» یعنی از چشم انداختن."},{"de":"Ich bitte vielmals um Entschuldigung für die Unannehmlichkeiten.","fa":"بابت این ناراحتی‌ها صمیمانه عذرخواهی می‌کنم.","note":"بسیار رسمی؛ مناسب ایمیل‌های کاری و خدمات مشتری."},{"de":"Das ist allein meine Schuld, ich kümmere mich darum.","fa":"این فقط تقصیر من است، خودم درستش می‌کنم.","note":"پذیرش مسئولیت؛ «sich um etwas kümmern» یعنی رسیدگی کردن."},{"de":"Schon gut, ich bin dir nicht böse.","fa":"اشکالی ندارد، از تو دلخور نیستم.","note":"پاسخ دوستانه به عذرخواهی؛ «Schon gut» یعنی عیبی ندارد."}]},{"day":45,"theme":"Danken und Komplimente","theme_fa":"تشکر و تعریف کردن","s":[{"de":"Tausend Dank, du hast mir echt den Tag gerettet!","fa":"هزار بار ممنون، واقعاً روزم را نجات دادی!","note":"محاوره‌ای و گرم؛ «jemandem den Tag retten»."},{"de":"Ich möchte mich ganz herzlich für Ihre Unterstützung bedanken.","fa":"می‌خواهم صمیمانه از حمایت شما تشکر کنم.","note":"«sich bedanken für» رسمی است؛ مناسب ایمیل و سخنرانی."},{"de":"Die neue Frisur steht dir richtig gut!","fa":"مدل موی جدید خیلی بهت می‌آید!","note":"«jemandem stehen» یعنی به کسی آمدن (برای لباس و مدل مو)."},{"de":"Sie haben eine sehr schöne Wohnung, so gemütlich!","fa":"خانه‌ی خیلی قشنگی دارید، چقدر دنج است!","note":"«gemütlich» یعنی دنج و راحت؛ تعریفی رایج در مهمانی."},{"de":"Danke für das Kompliment, das freut mich wirklich.","fa":"ممنون از تعریفتان، واقعاً خوشحالم کرد.","note":"پاسخ طبیعی به تعریف؛ آلمانی‌ها تعریف را ساده و بدون تعارف می‌پذیرند."}]},{"day":46,"theme":"Ratschläge geben","theme_fa":"توصیه و راهنمایی کردن","s":[{"de":"Mein Tipp: Fang lieber früh mit dem Lernen an, nicht erst kurz vor der Prüfung.","fa":"توصیه‌ام این است: بهتر است زود درس خواندن را شروع کنی، نه درست قبل از امتحان.","note":"«lieber» یعنی بهتر است؛ «anfangen mit» یعنی شروع کردن چیزی."},{"de":"Am besten rufst du gleich morgen früh beim Amt an.","fa":"بهترین کار این است که همین فردا صبح به اداره زنگ بزنی.","note":"«Am besten ...» ساده و رایج برای توصیه است؛ «beim Amt anrufen»."},{"de":"Pass auf, dass du die Frist nicht verpasst.","fa":"مواظب باش مهلت را از دست ندهی.","note":"«aufpassen, dass» یعنی مراقب بودن؛ «die Frist» یعنی مهلت."},{"de":"Warum fragst du nicht einfach mal deine Kollegen?","fa":"چرا خیلی ساده از همکارانت نمی‌پرسی؟","note":"توصیه به‌شکل سؤال منفی؛ غیرمستقیم و دوستانه."},{"de":"Ich kann Ihnen nur empfehlen, sich frühzeitig zu bewerben.","fa":"فقط می‌توانم به شما توصیه کنم که زود درخواست بدهید.","note":"«Ich kann nur empfehlen» توصیه را تأکیدی می‌کند؛ «sich bewerben» یعنی درخواست دادن."}]},{"day":47,"theme":"Vorschläge machen","theme_fa":"پیشنهاد دادن","s":[{"de":"Sollen wir eine kurze Pause machen?","fa":"یک استراحت کوتاه کنیم؟","note":"«Sollen wir ...?» پیشنهادی ساده به گروه است."},{"de":"Wie wäre es mit einem Spaziergang am Fluss?","fa":"یک پیاده‌روی کنار رودخانه چطور است؟","note":"«Wie wäre es mit + Dativ?» کوتاه‌تر از ساختار با «wenn» است."},{"de":"Mein Vorschlag wäre, die Aufgaben im Team aufzuteilen.","fa":"پیشنهاد من این است که کارها را در تیم تقسیم کنیم.","note":"«Mein Vorschlag wäre» مؤدبانه و مناسب جلسات است."},{"de":"Was meinst du, sollen wir lieber zu Hause bleiben?","fa":"نظرت چیست، بهتر نیست خانه بمانیم؟","note":"«Was meinst du?» نظر طرف را می‌پرسد؛ «lieber» یعنی ترجیحاً."},{"de":"Ich hätte da eine Idee: Wir könnten das Treffen online machen.","fa":"یک ایده دارم: می‌توانیم جلسه را آنلاین برگزار کنیم.","note":"«Ich hätte da eine Idee» مقدمه‌ای مؤدبانه برای پیشنهاد است."}]},{"day":48,"theme":"Einladen und reagieren","theme_fa":"دعوت کردن و پاسخ به دعوت","s":[{"de":"Wir machen am Freitag einen kleinen Spieleabend. Bist du dabei?","fa":"جمعه یک شب بازی کوچک داریم. تو هم هستی؟","note":"«Bist du dabei?» یعنی تو هم می‌آیی یا شرکت می‌کنی؟"},{"de":"Ich möchte Sie herzlich zu unserer Feier am 12. Mai einladen.","fa":"مایلم شما را صمیمانه به جشن ما در ۱۲ مه دعوت کنم.","note":"دعوت رسمی؛ «einladen zu + Dativ»."},{"de":"Ich muss erst noch in meinen Kalender schauen, ich sage dir morgen Bescheid.","fa":"اول باید تقویمم را نگاه کنم، فردا خبرت می‌کنم.","note":"پاسخ وقتی هنوز مطمئن نیستید؛ «Bescheid sagen» یعنی خبر دادن."},{"de":"Schade, da bin ich leider schon verabredet.","fa":"حیف، آن موقع متأسفانه قرار دیگری دارم.","note":"«verabredet sein» یعنی قرار داشتن؛ رد مؤدبانه‌ی دعوت."},{"de":"Ich nehme die Einladung gern an und freue mich auf den Abend.","fa":"دعوت را با کمال میل می‌پذیرم و منتظر آن شب هستم.","note":"پذیرش رسمی در ایمیل؛ «eine Einladung annehmen»."}]},{"day":49,"theme":"Überraschung und Zweifel ausdrücken","theme_fa":"بیان تعجب و تردید","s":[{"de":"Wirklich? Damit habe ich überhaupt nicht gerechnet.","fa":"واقعاً؟ اصلاً انتظارش را نداشتم.","note":"«rechnen mit» یعنی انتظار چیزی را داشتن."},{"de":"Das ist ja eine Überraschung!","fa":"عجب غافلگیری‌ای!","note":"«ja» در جمله‌ی خبری تعجب را نشان می‌دهد."},{"de":"Ob das wirklich so einfach funktioniert?","fa":"یعنی واقعاً به همین سادگی جواب می‌دهد؟","note":"سؤال با «Ob» در ابتدا و بدون جمله‌ی اصلی، تردید را بیان می‌کند."},{"de":"Das kommt mir irgendwie komisch vor.","fa":"این به نظرم یک جورهایی عجیب است.","note":"«jemandem komisch vorkommen» یعنی به نظر کسی عجیب آمدن."},{"de":"Ich kann kaum glauben, dass schon wieder ein Jahr vorbei ist.","fa":"باورم نمی‌شود که باز یک سال گذشت.","note":"«kaum» یعنی به‌زحمت؛ برای تعجب از گذر زمان."}]},{"day":50,"theme":"Nachfragen, wenn man nicht versteht","theme_fa":"دوباره پرسیدن وقتی متوجه نمی‌شویم","s":[{"de":"Wie schreibt man das? Könnten Sie es mir bitte buchstabieren?","fa":"این چطور نوشته می‌شود؟ ممکن است لطفاً برایم هجی کنید؟","note":"«buchstabieren» یعنی هجی کردن؛ برای اسم‌ها و آدرس‌ها پشت تلفن."},{"de":"Was bedeutet eigentlich „Kündigungsfrist“?","fa":"راستی «Kündigungsfrist» یعنی چه؟","note":"برای پرسیدن معنی واژه؛ «eigentlich» سؤال را طبیعی‌تر می‌کند."},{"de":"Ich bin nicht sicher, ob ich alles richtig mitbekommen habe.","fa":"مطمئن نیستم همه چیز را درست متوجه شده باشم.","note":"«mitbekommen» در محاوره یعنی متوجه شدن یا شنیدن."},{"de":"Meinen Sie damit, dass ich das Formular neu ausfüllen muss?","fa":"منظورتان این است که باید فرم را دوباره پر کنم؟","note":"برای اطمینان از منظور گوینده: «Meinen Sie damit, dass ...?»"},{"de":"Darf ich kurz nachfragen: Bis wann muss ich mich anmelden?","fa":"اجازه هست یک سؤال دیگر بپرسم: تا کی باید ثبت‌نام کنم؟","note":"«nachfragen» یعنی دوباره یا تکمیلی پرسیدن؛ مؤدبانه است."}]},{"day":51,"theme":"An der Uni: Sprechstunde und Professoren","theme_fa":"در دانشگاه: ساعت مشاوره و استادان","s":[{"de":"Ich hätte eine kurze Frage zu meiner Hausarbeit, haben Sie einen Moment Zeit?","fa":"یک سؤال کوتاه درباره‌ی تحقیق کلاسی‌ام دارم، یک لحظه وقت دارید؟","note":"شروع مؤدبانه‌ی گفت‌وگو با استاد؛ hätte (Konjunktiv II) لحن را مؤدبانه‌تر می‌کند."},{"de":"Wann bieten Sie in diesem Semester Ihre Sprechstunde an?","fa":"این ترم ساعت مشاوره‌تان چه زمانی است؟","note":"Sprechstunde = ساعتی که استاد پاسخگوی دانشجویان است؛ رسمی با Sie."},{"de":"Könnten Sie mir vielleicht ein paar Literaturhinweise zu diesem Thema geben?","fa":"ممکن است چند منبع درباره‌ی این موضوع به من معرفی کنید؟","note":"Literaturhinweise = معرفی منابع؛ vielleicht درخواست را نرم‌تر می‌کند."},{"de":"Ich würde gern mit Ihnen über die Bewertung meiner Klausur sprechen.","fa":"مایلم درباره‌ی نمره‌ی امتحانم با شما صحبت کنم.","note":"برای اعتراض مؤدبانه به نمره؛ Klausur = امتحان کتبی در دانشگاه."},{"de":"Wäre es möglich, die Abgabefrist um eine Woche zu verlängern?","fa":"امکانش هست مهلت تحویل را یک هفته تمدید کنید؟","note":"Wäre es möglich, … zu + Infinitiv: ساختاری بسیار مؤدبانه برای درخواست."}]},{"day":52,"theme":"Referat und Präsentation halten","theme_fa":"ارائه‌ی کلاسی و سخنرانی","s":[{"de":"In meinem Referat geht es um die Folgen der Digitalisierung.","fa":"ارائه‌ی من درباره‌ی پیامدهای دیجیتالی‌شدن است.","note":"es geht um + Akkusativ برای معرفی موضوع اصلی ارائه."},{"de":"Zunächst gebe ich Ihnen einen kurzen Überblick über die Gliederung.","fa":"ابتدا مروری کوتاه بر ساختار ارائه می‌کنم.","note":"Gliederung = ساختار و بخش‌بندی؛ جمله‌ی رایج آغاز ارائه."},{"de":"Damit komme ich zum zweiten Punkt meines Vortrags.","fa":"با این توضیح به نکته‌ی دوم سخنرانی‌ام می‌رسم.","note":"برای گذار بین بخش‌ها؛ damit اینجا یعنی «با این»."},{"de":"Wie Sie auf dieser Folie sehen können, ist die Zahl deutlich gestiegen.","fa":"همان‌طور که در این اسلاید می‌بینید، این رقم به‌طور چشمگیری بالا رفته است.","note":"Folie = اسلاید؛ برای ارجاع به تصویر یا نمودار."},{"de":"Vielen Dank für Ihre Aufmerksamkeit, ich freue mich auf Ihre Fragen.","fa":"از توجه شما سپاسگزارم، منتظر سؤال‌هایتان هستم.","note":"پایان استاندارد ارائه؛ sich freuen auf = مشتاق چیزی در آینده بودن."}]},{"day":53,"theme":"In der Diskussion: Argumentieren","theme_fa":"در بحث: استدلال کردن","s":[{"de":"Ich sehe das etwas anders, und zwar aus folgendem Grund.","fa":"من این را کمی متفاوت می‌بینم، آن هم به این دلیل.","note":"مخالفت ملایم؛ und zwar توضیح دقیق‌تر را معرفی می‌کند."},{"de":"Da muss ich Ihnen widersprechen, die Zahlen sprechen eine andere Sprache.","fa":"اینجا باید با شما مخالفت کنم؛ آمار چیز دیگری می‌گوید.","note":"widersprechen + Dativ؛ «die Zahlen sprechen eine andere Sprache» اصطلاحی رایج است."},{"de":"Das ist ein berechtigter Einwand, trotzdem sollte man die Kosten bedenken.","fa":"اعتراض بجایی است، با این حال باید هزینه‌ها را هم در نظر گرفت.","note":"اول پذیرفتن نظر مخالف، بعد استدلال خود؛ بعد از trotzdem فعل می‌آید."},{"de":"Lassen Sie mich bitte ausreden, ich bin gleich fertig.","fa":"لطفاً بگذارید حرفم را تمام کنم، الان تمام می‌شود.","note":"وقتی کسی حرفتان را قطع می‌کند؛ ausreden = حرف را تا آخر زدن."},{"de":"Ein wichtiges Argument dafür ist, dass die Maßnahme langfristig Geld spart.","fa":"یک دلیل مهم به نفع آن این است که این اقدام در درازمدت هزینه را کم می‌کند.","note":"dafür = در تأیید، dagegen = در رد؛ برای آوردن استدلال."}]},{"day":54,"theme":"Wissenschaftliches Schreiben","theme_fa":"نگارش علمی","s":[{"de":"Die vorliegende Arbeit untersucht den Einfluss sozialer Medien auf Jugendliche.","fa":"پژوهش حاضر تأثیر شبکه‌های اجتماعی را بر نوجوانان بررسی می‌کند.","note":"die vorliegende Arbeit = اثر حاضر؛ آغاز رایج مقدمه‌ی مقاله."},{"de":"Im Folgenden werden die wichtigsten Ergebnisse dargestellt.","fa":"در ادامه مهم‌ترین نتایج ارائه می‌شوند.","note":"مجهول (werden + Partizip II) در متن علمی بسیار رایج است."},{"de":"Laut einer aktuellen Studie leidet jeder fünfte Student unter Stress.","fa":"طبق یک پژوهش جدید، از هر پنج دانشجو یک نفر از استرس رنج می‌برد.","note":"laut برای ذکر منبع؛ leiden unter + Dativ = رنج بردن از."},{"de":"Diese These lässt sich anhand mehrerer Beispiele belegen.","fa":"این فرضیه را می‌توان با چند مثال اثبات کرد.","note":"sich lassen + Infinitiv = «می‌توان…»؛ anhand + Genitiv = بر پایه‌ی."},{"de":"Zusammenfassend kann man sagen, dass weitere Forschung notwendig ist.","fa":"در جمع‌بندی می‌توان گفت که پژوهش بیشتری لازم است.","note":"عبارت مناسب بخش نتیجه‌گیری؛ بعد از آن جمله‌ی dass می‌آید."}]},{"day":55,"theme":"Prüfungen und Lernen","theme_fa":"امتحان و درس خواندن","s":[{"de":"Ich bin total aufgeregt, morgen schreibe ich meine erste Klausur.","fa":"خیلی استرس دارم، فردا اولین امتحانم را می‌دهم.","note":"eine Klausur schreiben = امتحان کتبی دادن؛ aufgeregt = مضطرب/هیجان‌زده."},{"de":"Wollen wir zusammen lernen? Zu zweit ist es weniger anstrengend.","fa":"می‌خواهی با هم درس بخوانیم؟ دونفری کمتر خسته‌کننده است.","note":"Wollen wir …? پیشنهادی دوستانه؛ zu zweit = دونفری."},{"de":"Ich habe die ganze Nacht durchgelernt und bin jetzt völlig fertig.","fa":"تمام شب یکسره درس خواندم و الان کاملاً از پا افتاده‌ام.","note":"fertig sein در محاوره = خیلی خسته بودن؛ durchlernen = بی‌وقفه درس خواندن."},{"de":"Zum Glück habe ich die Prüfung beim ersten Versuch bestanden.","fa":"خوشبختانه امتحان را همان بار اول قبول شدم.","note":"bestehen = قبول شدن؛ متضادش durchfallen است."},{"de":"Ich muss mir den Stoff besser einteilen, sonst schaffe ich das nicht.","fa":"باید مطالب را بهتر تقسیم کنم، وگرنه از پسش برنمی‌آیم.","note":"der Stoff = مطالب درسی؛ بعد از sonst فعل می‌آید."}]},{"day":56,"theme":"Bewerbung und Vorstellungsgespräch","theme_fa":"درخواست کار و مصاحبه‌ی استخدامی","s":[{"de":"Mit großem Interesse habe ich Ihre Stellenanzeige gelesen.","fa":"آگهی استخدام شما را با علاقه‌ی فراوان خواندم.","note":"شروع کلاسیک نامه‌ی درخواست کار (Anschreiben)."},{"de":"Ich bringe mehrjährige Erfahrung im Projektmanagement mit.","fa":"چندین سال تجربه در مدیریت پروژه دارم.","note":"mitbringen در مصاحبه یعنی داشتن تجربه یا مهارت لازم برای شغل."},{"de":"Meine größte Stärke ist, dass ich auch unter Druck den Überblick behalte.","fa":"بزرگ‌ترین نقطه‌ی قوتم این است که حتی زیر فشار هم کنترل اوضاع را از دست نمی‌دهم.","note":"پاسخ به سؤال رایج نقاط قوت؛ den Überblick behalten = اشراف داشتن."},{"de":"Was würde in den ersten Monaten zu meinen Aufgaben gehören?","fa":"در ماه‌های اول چه کارهایی جزو وظایف من خواهد بود؟","note":"سؤالی خوب برای پایان مصاحبه؛ gehören zu = جزو چیزی بودن."},{"de":"Ab wann wäre die Stelle zu besetzen?","fa":"این موقعیت شغلی از چه زمانی باید پر شود؟","note":"پرسیدن تاریخ شروع کار؛ eine Stelle besetzen = کسی را برای پستی استخدام کردن."}]},{"day":57,"theme":"Im Büro: Meetings","theme_fa":"در دفتر: جلسه‌ها","s":[{"de":"Lassen Sie uns kurz die Tagesordnung durchgehen.","fa":"بیایید سریع دستور جلسه را مرور کنیم.","note":"Tagesordnung = دستور جلسه؛ Lassen Sie uns برای پیشنهاد رسمی."},{"de":"Könnten wir diesen Punkt auf das nächste Meeting verschieben?","fa":"می‌توانیم این موضوع را به جلسه‌ی بعد موکول کنیم؟","note":"verschieben auf + Akkusativ = به تعویق انداختن تا زمانی مشخص."},{"de":"Ich fasse kurz zusammen, was wir bisher beschlossen haben.","fa":"به‌طور خلاصه می‌گویم تا اینجا چه تصمیم‌هایی گرفته‌ایم.","note":"beschließen = تصمیم گرفتن (رسمی)؛ مناسب پایان جلسه."},{"de":"Wer schreibt heute das Protokoll?","fa":"امروز چه کسی صورت‌جلسه را می‌نویسد؟","note":"Protokoll در جلسه یعنی صورت‌جلسه، نه «پروتکل»."},{"de":"Entschuldigung, darf ich hier kurz etwas ergänzen?","fa":"ببخشید، اجازه هست اینجا نکته‌ای اضافه کنم؟","note":"ergänzen = تکمیل کردن؛ راه مؤدبانه برای وارد شدن به بحث."}]},{"day":58,"theme":"Formelle E-Mails: Anfang und Schluss","theme_fa":"ایمیل رسمی: آغاز و پایان","s":[{"de":"Sehr geehrte Frau Becker, vielen Dank für Ihre schnelle Rückmeldung.","fa":"خانم بکر گرامی، از پاسخ سریعتان بسیار سپاسگزارم.","note":"بعد از خطاب ویرگول می‌آید و ادامه با حرف کوچک شروع می‌شود."},{"de":"Ich wende mich an Sie, weil ich eine Frage zu meiner Rechnung habe.","fa":"با شما تماس می‌گیرم، چون درباره‌ی صورتحسابم سؤالی دارم.","note":"sich wenden an + Akkusativ = مراجعه کردن به؛ شروع رسمی ایمیل."},{"de":"Im Anhang finden Sie die gewünschten Unterlagen.","fa":"مدارک درخواستی را در پیوست ملاحظه می‌فرمایید.","note":"Anhang = پیوست؛ جمله‌ی استاندارد برای فایل ضمیمه."},{"de":"Für Rückfragen stehe ich Ihnen gern zur Verfügung.","fa":"برای هر پرسش دیگری با کمال میل در خدمتتان هستم.","note":"zur Verfügung stehen = در دسترس بودن؛ پیش از خداحافظی رسمی."},{"de":"Ich freue mich auf Ihre Antwort und verbleibe mit freundlichen Grüßen.","fa":"منتظر پاسخ شما هستم. با احترام","note":"verbleiben بسیار رسمی و کمی قدیمی است؛ اغلب Mit freundlichen Grüßen به‌تنهایی کافی است."}]},{"day":59,"theme":"Mit Kollegen sprechen","theme_fa":"صحبت با همکاران","s":[{"de":"Na, wie war dein Wochenende? Hast du was Schönes gemacht?","fa":"خب، آخر هفته‌ات چطور بود؟ کار جالبی کردی؟","note":"small talk رایج دوشنبه صبح؛ was در محاوره = etwas."},{"de":"Wollen wir uns duzen? Ich bin übrigens Jonas.","fa":"موافقی همدیگر را «تو» خطاب کنیم؟ راستی من یوناس هستم.","note":"duzen = با du صحبت کردن؛ معمولاً فرد مسن‌تر یا ارشد پیشنهاد می‌دهد."},{"de":"Gehst du mit in die Kantine, oder hast du schon gegessen?","fa":"با ما به غذاخوری می‌آیی یا غذا خورده‌ای؟","note":"mitgehen = همراه رفتن؛ Kantine = غذاخوری محل کار."},{"de":"Kannst du mir kurz zeigen, wie der neue Drucker funktioniert?","fa":"می‌توانی سریع نشانم بدهی پرینتر جدید چطور کار می‌کند؟","note":"درخواست کمک غیررسمی؛ kurz لحن را سبک‌تر می‌کند."},{"de":"Danke, dass du für mich eingesprungen bist, ich schulde dir was.","fa":"ممنون که جای من کار کردی، یکی طلبت.","note":"einspringen = جای کسی را پر کردن؛ ich schulde dir was = مدیونتم."}]},{"day":60,"theme":"Probleme bei der Arbeit lösen","theme_fa":"حل مشکلات کاری","s":[{"de":"Wir haben ein Problem mit dem Server, die Kunden können sich nicht einloggen.","fa":"با سرور مشکل داریم؛ مشتری‌ها نمی‌توانند وارد حساب شوند.","note":"گزارش دقیق مشکل: اول خود مشکل، بعد پیامدش."},{"de":"Woran könnte das liegen?","fa":"علتش چه می‌تواند باشد؟","note":"liegen an + Dativ = علتش … بودن؛ پرسش رایج برای عیب‌یابی."},{"de":"Ich schlage vor, dass wir zuerst die Ursache klären.","fa":"پیشنهاد می‌کنم اول علت را روشن کنیم.","note":"vorschlagen, dass … برای پیشنهاد رسمی؛ die Ursache = علت."},{"de":"Bis wann können Sie mir eine Lösung anbieten?","fa":"تا کی می‌توانید راه‌حلی به من پیشنهاد کنید؟","note":"پرسیدن مهلت؛ Bis wann? = تا کی؟"},{"de":"Ich kümmere mich darum und melde mich heute Nachmittag bei dir.","fa":"من پیگیرش می‌شوم و امروز بعدازظهر خبرت می‌کنم.","note":"sich kümmern um = رسیدگی کردن؛ sich melden bei = خبر دادن به کسی."}]},{"day":61,"theme":"Sich beschweren","theme_fa":"شکایت کردن","s":[{"de":"Ich möchte mich über den Service in Ihrer Filiale beschweren.","fa":"می‌خواهم از خدمات شعبه‌ی شما شکایت کنم.","note":"sich beschweren über + Akkusativ؛ مرجع شکایت با bei + Dativ."},{"de":"Das Gerät ist nach nur zwei Wochen kaputtgegangen.","fa":"دستگاه فقط بعد از دو هفته خراب شد.","note":"kaputtgehen با sein صرف می‌شود؛ بیان مشخص مشکل."},{"de":"Ich habe schon dreimal angerufen, aber niemand hat sich zurückgemeldet.","fa":"تا حالا سه بار تماس گرفته‌ام، اما هیچ‌کس جوابم را نداده است.","note":"sich zurückmelden = دوباره تماس گرفتن و پاسخ دادن."},{"de":"Ich erwarte, dass Sie mir den vollen Betrag erstatten.","fa":"انتظار دارم کل مبلغ را به من برگردانید.","note":"لحن قاطع اما مؤدب؛ erstatten = بازپرداخت کردن."},{"de":"Ehrlich gesagt bin ich von Ihrem Kundenservice sehr enttäuscht.","fa":"راستش را بخواهید، از خدمات مشتریان شما خیلی ناامید شده‌ام.","note":"enttäuscht von = ناامید از؛ ehrlich gesagt برای صراحت."}]},{"day":62,"theme":"Verhandeln und Kompromisse finden","theme_fa":"مذاکره و پیدا کردن راه میانه","s":[{"de":"Wie wäre es, wenn wir uns in der Mitte treffen?","fa":"چطور است هر دو کمی کوتاه بیاییم و وسط راه توافق کنیم؟","note":"sich in der Mitte treffen = هر دو طرف به یک اندازه کوتاه آمدن."},{"de":"Bei diesem Preis kann ich Ihnen leider nicht entgegenkommen.","fa":"متأسفانه در این قیمت نمی‌توانم با شما راه بیایم.","note":"entgegenkommen + Dativ = امتیاز دادن، راه آمدن."},{"de":"Wenn Sie den Vertrag für zwei Jahre abschließen, bekommen Sie zehn Prozent Rabatt.","fa":"اگر قرارداد دوساله ببندید، ده درصد تخفیف می‌گیرید.","note":"شرط + امتیاز: الگوی رایج در مذاکره؛ einen Vertrag abschließen = قرارداد بستن."},{"de":"Damit könnte ich leben, wenn die Lieferung pünktlich kommt.","fa":"اگر تحویل به‌موقع باشد، با این کنار می‌آیم.","note":"damit kann ich leben = می‌توانم قبولش کنم (محاوره‌ای و رایج)."},{"de":"Lassen Sie uns eine Lösung finden, mit der beide Seiten zufrieden sind.","fa":"بیایید راه‌حلی پیدا کنیم که هر دو طرف از آن راضی باشند.","note":"جمله‌ی موصولی با mit der، چون zufrieden mit + Dativ است."}]},{"day":63,"theme":"Über Erfahrungen berichten","theme_fa":"تعریف کردن تجربه‌ها","s":[{"de":"Als ich nach Deutschland kam, konnte ich kaum ein Wort Deutsch.","fa":"وقتی به آلمان آمدم، تقریباً هیچ کلمه‌ی آلمانی بلد نبودم.","note":"als برای یک رویداد واحد در گذشته؛ kaum = به‌زحمت."},{"de":"Ich habe die Erfahrung gemacht, dass man hier alles schriftlich braucht.","fa":"تجربه‌ام این بوده که اینجا همه‌چیز را باید کتبی داشت.","note":"die Erfahrung machen ترکیب ثابت است، نه «Erfahrung haben»."},{"de":"Am Anfang war das für mich eine ziemliche Umstellung.","fa":"اول کار، کنار آمدن با این برایم نسبتاً سخت بود.","note":"Umstellung = عادت کردن به شرایط جدید؛ ziemlich = نسبتاً."},{"de":"Im Nachhinein bin ich froh, dass ich das Praktikum gemacht habe.","fa":"حالا که به گذشته نگاه می‌کنم، خوشحالم که آن کارآموزی را انجام دادم.","note":"im Nachhinein = با نگاه به گذشته."},{"de":"So etwas habe ich noch nie erlebt.","fa":"تا حالا چنین چیزی ندیده بودم.","note":"erleben = از سر گذراندن؛ برای ابراز تعجب از یک اتفاق."}]},{"day":64,"theme":"Pläne und Ziele beschreiben","theme_fa":"توصیف برنامه‌ها و هدف‌ها","s":[{"de":"Ich habe vor, nächstes Jahr meinen Master in Berlin zu machen.","fa":"قصد دارم سال آینده کارشناسی ارشدم را در برلین بخوانم.","note":"vorhaben, … zu + Infinitiv = قصد داشتن."},{"de":"Mein Ziel ist es, bis Ende des Jahres die C1-Prüfung zu bestehen.","fa":"هدفم این است که تا پایان سال آزمون C1 را قبول شوم.","note":"Mein Ziel ist es, … zu: بیان رسمی هدف."},{"de":"Langfristig möchte ich mich selbstständig machen.","fa":"در درازمدت می‌خواهم کار خودم را راه بیندازم.","note":"sich selbstständig machen = کسب‌وکار مستقل راه انداختن."},{"de":"Ich spiele mit dem Gedanken, in eine andere Stadt zu ziehen.","fa":"به فکر نقل مکان به شهر دیگری افتاده‌ام.","note":"mit dem Gedanken spielen = به چیزی فکر کردن ولی هنوز تصمیم قطعی نگرفتن."},{"de":"Erst mal will ich die Probezeit überstehen, dann sehen wir weiter.","fa":"فعلاً می‌خواهم دوره‌ی آزمایشی را پشت سر بگذارم، بعد ببینیم چه می‌شود.","note":"dann sehen wir weiter (محاوره) = بعداً تصمیم می‌گیریم."}]},{"day":65,"theme":"Vor- und Nachteile abwägen","theme_fa":"سنجیدن مزایا و معایب","s":[{"de":"Einerseits ist die Wohnung günstig, andererseits liegt sie weit außerhalb.","fa":"از یک طرف آپارتمان ارزان است، از طرف دیگر خیلی بیرون شهر است.","note":"einerseits … andererseits برای مقایسه‌ی دو جنبه‌ی یک موضوع."},{"de":"Ein großer Vorteil ist, dass man flexibel arbeiten kann.","fa":"یک مزیت بزرگ این است که می‌توان با ساعت کاری منعطف کار کرد.","note":"Ein Vorteil/Nachteil ist, dass … ساختار پایه‌ی این مبحث."},{"de":"Der Nachteil dabei ist, dass man oft allein arbeitet.","fa":"عیبش این است که آدم اغلب تنها کار می‌کند.","note":"dabei = در این مورد؛ man با فعل مفرد."},{"de":"Alles in allem überwiegen für mich die Vorteile.","fa":"روی‌هم‌رفته، برای من مزایا بیشتر است.","note":"überwiegen = غالب بودن؛ alles in allem برای نتیجه‌گیری."},{"de":"Man muss genau abwägen, ob sich der Aufwand lohnt.","fa":"باید دقیق سنجید که آیا این زحمت می‌ارزد یا نه.","note":"sich lohnen = ارزش داشتن؛ der Aufwand = زحمت و هزینه."}]},{"day":66,"theme":"Grafiken und Statistiken beschreiben","theme_fa":"توصیف نمودارها و آمار","s":[{"de":"Die Grafik zeigt, wie sich die Mietpreise seit 2010 entwickelt haben.","fa":"نمودار نشان می‌دهد اجاره‌بها از سال ۲۰۱۰ چه روندی داشته است.","note":"sich entwickeln = روند داشتن؛ جمله‌ی آغازین توصیف نمودار."},{"de":"Die Daten stammen vom Statistischen Bundesamt.","fa":"داده‌ها از اداره‌ی آمار فدرال آلمان است.","note":"stammen von/aus = منشأ داشتن؛ برای ذکر منبع آمار."},{"de":"Der Anteil der Frauen ist um zwölf Prozent gestiegen.","fa":"سهم زنان دوازده درصد افزایش یافته است.","note":"um + عدد = میزان تغییر؛ auf + عدد = مقدار نهایی."},{"de":"Auffällig ist, dass die Zahlen im Jahr 2020 stark zurückgegangen sind.","fa":"نکته‌ی قابل توجه این است که ارقام در سال ۲۰۲۰ به‌شدت کاهش یافته‌اند.","note":"Auffällig ist, dass … برای اشاره به نکته‌ی برجسته‌ی نمودار."},{"de":"Fast die Hälfte der Befragten gab an, täglich Sport zu treiben.","fa":"تقریباً نیمی از پاسخ‌دهندگان گفتند که هر روز ورزش می‌کنند.","note":"die Befragten = پاسخ‌دهندگان نظرسنجی؛ angeben = اظهار کردن."}]},{"day":67,"theme":"Zusammenfassen","theme_fa":"خلاصه کردن","s":[{"de":"Kurz gesagt geht es in dem Artikel um den Fachkräftemangel.","fa":"خلاصه اینکه، مقاله درباره‌ی کمبود نیروی متخصص است.","note":"kurz gesagt = به‌طور خلاصه؛ برای بیان سریع موضوع اصلی."},{"de":"Der Autor vertritt die Meinung, dass Schulen mehr Geld brauchen.","fa":"نویسنده بر این عقیده است که مدارس به بودجه‌ی بیشتری نیاز دارند.","note":"eine Meinung vertreten = از دیدگاهی دفاع کردن."},{"de":"Die wichtigsten Punkte lassen sich wie folgt zusammenfassen.","fa":"مهم‌ترین نکات را می‌توان این‌گونه خلاصه کرد.","note":"wie folgt = به شرح زیر؛ رسمی و نوشتاری."},{"de":"Im Großen und Ganzen sind sich alle Experten einig.","fa":"در کل، همه‌ی کارشناسان هم‌نظرند.","note":"sich einig sein = هم‌نظر بودن؛ im Großen und Ganzen = روی‌هم‌رفته."},{"de":"Zum Schluss betont der Text, wie wichtig frühe Förderung ist.","fa":"در پایان، متن تأکید می‌کند که حمایت زودهنگام چقدر مهم است.","note":"betonen = تأکید کردن؛ مناسب گزارش محتوای یک متن."}]},{"day":68,"theme":"Nachrichten und Politik","theme_fa":"اخبار و سیاست","s":[{"de":"Hast du mitbekommen, was gestern im Bundestag beschlossen wurde?","fa":"خبر داری دیروز در مجلس فدرال چه تصویب شد؟","note":"mitbekommen (محاوره) = باخبر شدن، شنیدن."},{"de":"Die Regierung plant, das Rentenalter schrittweise anzuheben.","fa":"دولت قصد دارد سن بازنشستگی را به‌تدریج بالا ببرد.","note":"anheben = بالا بردن؛ واژه‌ای رسمی در زبان اخبار."},{"de":"Ich finde, die Politiker sollten mehr auf die Bürger hören.","fa":"به نظرم سیاستمداران باید بیشتر به حرف مردم گوش کنند.","note":"hören auf + Akkusativ = به حرف کسی گوش دادن."},{"de":"In den Nachrichten hieß es, dass die Verhandlungen gescheitert sind.","fa":"در اخبار گفتند که مذاکرات شکست خورده است.","note":"es hieß = گفته شد؛ scheitern با sein صرف می‌شود."},{"de":"Mich würde interessieren, wie du zu diesem Thema stehst.","fa":"برایم جالب است بدانم نظرت درباره‌ی این موضوع چیست.","note":"stehen zu = نظری درباره‌ی چیزی داشتن؛ پرسش غیرمستقیم و مؤدبانه."}]},{"day":69,"theme":"Umwelt und Nachhaltigkeit","theme_fa":"محیط زیست و پایداری","s":[{"de":"Ich versuche, so wenig Plastik wie möglich zu benutzen.","fa":"سعی می‌کنم تا جای ممکن کمتر پلاستیک مصرف کنم.","note":"so wenig wie möglich = تا حد امکان کم."},{"de":"Seit einem Jahr fahre ich fast nur noch mit dem Fahrrad zur Arbeit.","fa":"از یک سال پیش تقریباً فقط با دوچرخه سر کار می‌روم.","note":"nur noch = دیگر فقط؛ نشانه‌ی تغییر عادت."},{"de":"Der Klimawandel betrifft uns alle, nicht nur die nächste Generation.","fa":"تغییرات اقلیمی به همه‌ی ما مربوط است، نه فقط به نسل بعد.","note":"betreffen + Akkusativ = مربوط شدن به، تحت تأثیر قرار دادن."},{"de":"Man sollte den Müll richtig trennen, sonst bringt Recycling wenig.","fa":"باید زباله را درست تفکیک کرد، وگرنه بازیافت فایده‌ی چندانی ندارد.","note":"Müll trennen = تفکیک زباله؛ در آلمان بسیار جدی گرفته می‌شود."},{"de":"Nachhaltig einzukaufen ist leider oft teurer.","fa":"خرید پایدار متأسفانه اغلب گران‌تر است.","note":"مصدر با zu می‌تواند فاعل جمله باشد."}]},{"day":70,"theme":"Gesundheit und Sport","theme_fa":"سلامت و ورزش","s":[{"de":"Ich fühle mich seit ein paar Tagen ziemlich schlapp.","fa":"چند روزی است که خیلی بی‌حالم.","note":"schlapp (محاوره) = بی‌حال؛ seit با زمان حال."},{"de":"Der Arzt hat mich für eine Woche krankgeschrieben.","fa":"دکتر برایم یک هفته گواهی استعلاجی نوشت.","note":"krankschreiben = گواهی بیماری دادن؛ در آلمان برای کارفرما لازم است."},{"de":"Ich gehe dreimal pro Woche ins Fitnessstudio, um fit zu bleiben.","fa":"هفته‌ای سه بار به باشگاه می‌روم تا سرحال بمانم.","note":"um … zu برای بیان هدف."},{"de":"Du solltest dich mehr schonen, sonst wirst du nicht gesund.","fa":"باید بیشتر مراقب خودت باشی و استراحت کنی، وگرنه خوب نمی‌شوی.","note":"sich schonen = به خود فشار نیاوردن."},{"de":"Seit ich regelmäßig jogge, schlafe ich viel besser.","fa":"از وقتی مرتب می‌دوم، خیلی بهتر می‌خوابم.","note":"seit به عنوان حرف ربط، همراه زمان حال."}]},{"day":71,"theme":"Digitales Leben und Medien","theme_fa":"زندگی دیجیتال و رسانه‌ها","s":[{"de":"Ich verbringe viel zu viel Zeit am Handy.","fa":"خیلی بیش از حد وقتم را پای گوشی می‌گذرانم.","note":"viel zu viel = خیلی زیادی؛ am Handy = پای گوشی."},{"de":"Kannst du mir den Link schicken? Ich finde den Artikel nicht.","fa":"می‌توانی لینک را برایم بفرستی؟ مقاله را پیدا نمی‌کنم.","note":"درخواستی ساده و روزمره در پیام‌رسان."},{"de":"Man sollte nicht alles glauben, was im Internet steht.","fa":"نباید هر چیزی را که در اینترنت نوشته شده باور کرد.","note":"stehen برای متن نوشته‌شده؛ بعد از alles از was استفاده می‌شود."},{"de":"Ich habe mein Passwort vergessen und komme nicht mehr in mein Konto.","fa":"رمزم را فراموش کرده‌ام و دیگر نمی‌توانم وارد حسابم شوم.","note":"in etwas kommen (محاوره) = وارد شدن؛ Konto = حساب."},{"de":"Mir ist wichtig, dass meine Daten geschützt sind.","fa":"برایم مهم است که اطلاعاتم محافظت شوند.","note":"Mir ist wichtig, dass … = برای من مهم است که…"}]},{"day":72,"theme":"Kultur und Freizeit","theme_fa":"فرهنگ و اوقات فراغت","s":[{"de":"Hast du Lust, am Samstag mit ins Theater zu kommen?","fa":"حوصله‌اش را داری شنبه با ما به تئاتر بیایی؟","note":"Lust haben, … zu = حال و حوصله داشتن؛ دعوت دوستانه."},{"de":"Die Ausstellung soll wirklich sehenswert sein.","fa":"می‌گویند نمایشگاه واقعاً دیدنی است.","note":"sollen برای نقل شنیده‌ها؛ sehenswert = دیدنی."},{"de":"In meiner Freizeit lese ich gern Krimis.","fa":"در اوقات فراغتم دوست دارم داستان جنایی بخوانم.","note":"Krimi = داستان یا فیلم جنایی؛ gern بعد از فعل می‌آید."},{"de":"Der Film hat mich echt berührt.","fa":"فیلم واقعاً تحت تأثیرم قرار داد.","note":"berühren = متأثر کردن؛ echt (محاوره) = واقعاً."},{"de":"Sollen wir die Karten lieber online reservieren, damit wir sicher noch welche bekommen?","fa":"بهتر نیست بلیت‌ها را آنلاین رزرو کنیم تا مطمئن شویم هنوز گیرمان می‌آید؟","note":"damit برای بیان هدف؛ welche اینجا یعنی «چندتایی از آن‌ها»."}]},{"day":73,"theme":"Interkulturelle Missverständnisse","theme_fa":"سوءتفاهم‌های بین‌فرهنگی","s":[{"de":"In meinem Heimatland wäre das unhöflich, deshalb war ich überrascht.","fa":"در کشور من این کار بی‌ادبی حساب می‌شد، برای همین تعجب کردم.","note":"wäre (Konjunktiv II) برای مقایسه‌ی فرضی بین دو فرهنگ."},{"de":"Ich wusste nicht, dass man hier so direkt Nein sagt.","fa":"نمی‌دانستم اینجا آدم‌ها این‌قدر رک «نه» می‌گویند.","note":"رک بودن در فرهنگ آلمانی معمولاً بی‌ادبی به حساب نمی‌آید."},{"de":"Entschuldigung, ich wollte Sie nicht beleidigen, das war ein Missverständnis.","fa":"ببخشید، نمی‌خواستم به شما توهین کنم؛ سوءتفاهم شد.","note":"beleidigen = توهین کردن؛ عذرخواهی صریح و روشن."},{"de":"Bei uns ist es üblich, dass man ein Angebot zuerst ablehnt.","fa":"پیش ما رسم است که آدم اول پیشنهاد را رد کند.","note":"برای توضیح «تعارف»؛ در آلمان Nein معمولاً واقعاً یعنی نه."},{"de":"Hier kommt man lieber pünktlich, sogar zu privaten Einladungen.","fa":"اینجا آدم‌ها ترجیح می‌دهند سر وقت برسند، حتی به مهمانی‌های خصوصی.","note":"pünktlich = سر وقت؛ نکته‌ی فرهنگی مهم در آلمان."}]},{"day":74,"theme":"Ärger und Konflikte entschärfen","theme_fa":"آرام کردن خشم و تنش","s":[{"de":"Ich verstehe, dass Sie verärgert sind.","fa":"درک می‌کنم که ناراحت و عصبانی هستید.","note":"به رسمیت شناختن احساس طرف مقابل، اولین قدم برای آرام کردن او."},{"de":"Lass uns erst mal tief durchatmen und in Ruhe darüber reden.","fa":"بیا اول یک نفس عمیق بکشیم و با آرامش درباره‌اش حرف بزنیم.","note":"durchatmen = نفس عمیق کشیدن؛ غیررسمی با du."},{"de":"Das war nicht böse gemeint.","fa":"منظور بدی نداشتم.","note":"gemeint sein = منظور بودن؛ برای رفع سوءتفاهم."},{"de":"Ich glaube, wir reden gerade aneinander vorbei.","fa":"فکر می‌کنم الان منظور همدیگر را نمی‌فهمیم.","note":"aneinander vorbeireden = هر کس درباره‌ی چیز دیگری حرف زدن."},{"de":"Können wir das sachlich klären, ohne laut zu werden?","fa":"می‌توانیم این را منطقی حل کنیم، بدون اینکه صدایمان بالا برود؟","note":"sachlich = منطقی و بی‌احساس؛ ohne … zu = بدون اینکه."}]},{"day":75,"theme":"Redewendungen im Alltag","theme_fa":"اصطلاحات روزمره","s":[{"de":"Das ist nicht mein Bier.","fa":"این به من ربطی ندارد.","note":"اصطلاح محاوره‌ای به معنای «مسئله‌ی من نیست»."},{"de":"Drück mir die Daumen, morgen habe ich das Vorstellungsgespräch!","fa":"برایم دعا کن، فردا مصاحبه دارم!","note":"die Daumen drücken = برای کسی آرزوی موفقیت کردن."},{"de":"Ich verstehe nur Bahnhof.","fa":"اصلاً هیچی نمی‌فهمم.","note":"اصطلاح بسیار رایج برای «هیچ چیز نفهمیدن»."},{"de":"Da hast du aber Schwein gehabt!","fa":"عجب شانسی آوردی!","note":"Schwein haben (محاوره) = خوش‌شانس بودن."},{"de":"Mach dir keinen Kopf, das wird schon.","fa":"غصه نخور، درست می‌شود.","note":"sich einen Kopf machen = نگران بودن؛ das wird schon = درست می‌شود."}]},{"day":76,"theme":"An der Uni: Sprechstunde und Professoren","theme_fa":"در دانشگاه: ساعت مشاوره و استادان","s":[{"de":"Entschuldigen Sie die Störung, ist das hier die Sprechstunde von Professor Wagner?","fa":"ببخشید مزاحم شدم، ساعت مشاوره‌ی پروفسور واگنر اینجاست؟","note":"Entschuldigen Sie die Störung: شروع مؤدبانه هنگام وارد شدن به دفتر."},{"de":"Ich bin mir unsicher, ob ich mein Thema genug eingegrenzt habe.","fa":"مطمئن نیستم موضوعم را به اندازه‌ی کافی محدود کرده باشم.","note":"ein Thema eingrenzen = محدود کردن موضوع؛ مهم برای پایان‌نامه."},{"de":"Würden Sie meine Bachelorarbeit betreuen?","fa":"حاضرید استاد راهنمای پایان‌نامه‌ی کارشناسی‌ام شوید؟","note":"betreuen = راهنمایی کردن؛ Betreuer/in = استاد راهنما."},{"de":"Darf ich fragen, worauf Sie bei der Bewertung besonders achten?","fa":"اجازه هست بپرسم در نمره‌دهی به چه چیزی بیشتر توجه می‌کنید؟","note":"achten auf + Akkusativ؛ برای پرسش از worauf استفاده می‌شود."},{"de":"Vielen Dank für Ihre Zeit, das hat mir sehr weitergeholfen.","fa":"خیلی ممنون بابت وقتی که گذاشتید، خیلی کمکم کرد.","note":"weiterhelfen = کمک کردن برای پیشرفت کار؛ پایان گفت‌وگو."}]},{"day":77,"theme":"Referat und Präsentation halten","theme_fa":"ارائه‌ی کلاسی و سخنرانی","s":[{"de":"Guten Morgen zusammen, heute möchte ich Ihnen das Thema Fast Fashion vorstellen.","fa":"صبح همگی به‌خیر، امروز می‌خواهم موضوع «مد سریع» را به شما معرفی کنم.","note":"zusammen = همگی؛ vorstellen برای معرفی موضوع."},{"de":"Mein Vortrag gliedert sich in drei Teile.","fa":"سخنرانی من از سه بخش تشکیل شده است.","note":"sich gliedern in + Akkusativ = تقسیم شدن به."},{"de":"An dieser Stelle möchte ich ein kurzes Beispiel geben.","fa":"در اینجا می‌خواهم مثال کوتاهی بزنم.","note":"an dieser Stelle = در این نقطه از ارائه."},{"de":"Falls Sie Fragen haben, können Sie mich gern jederzeit unterbrechen.","fa":"اگر سؤالی داشتید، هر وقت خواستید می‌توانید حرفم را قطع کنید.","note":"falls = در صورتی که؛ دعوت به پرسش در طول ارائه."},{"de":"Das war's von meiner Seite, gibt es noch Fragen?","fa":"از طرف من همین بود؛ سؤالی هست؟","note":"پایان کمی غیررسمی‌تر ارائه؛ Das war's = تمام شد."}]},{"day":78,"theme":"In der Diskussion: Argumentieren","theme_fa":"در بحث: استدلال کردن","s":[{"de":"Da bin ich ganz Ihrer Meinung.","fa":"در این مورد کاملاً با شما هم‌نظرم.","note":"jemandes Meinung sein (Genitiv) = با کسی هم‌نظر بودن."},{"de":"Das mag sein, aber man darf die Nachteile nicht vergessen.","fa":"شاید این‌طور باشد، ولی نباید معایب را فراموش کرد.","note":"Das mag sein = ممکن است؛ پذیرش نسبی پیش از مخالفت."},{"de":"Was genau meinen Sie damit?","fa":"دقیقاً منظورتان از این حرف چیست؟","note":"درخواست توضیح در بحث؛ damit = از این حرف."},{"de":"Ich bin fest davon überzeugt, dass Bildung kostenlos sein sollte.","fa":"قاطعانه معتقدم که آموزش باید رایگان باشد.","note":"überzeugt sein von؛ davon به جمله‌ی dass اشاره دارد."},{"de":"Darf ich kurz auf Ihr Argument eingehen?","fa":"اجازه هست کمی به استدلال شما بپردازم؟","note":"eingehen auf + Akkusativ = پرداختن به حرف کسی."}]},{"day":79,"theme":"Wissenschaftliches Schreiben","theme_fa":"نگارش علمی","s":[{"de":"Diese Arbeit verfolgt das Ziel, die Ursachen von Armut zu analysieren.","fa":"هدف این پژوهش تحلیل علل فقر است.","note":"ein Ziel verfolgen = هدفی را دنبال کردن؛ مناسب مقدمه."},{"de":"Bisher wurde diese Frage in der Forschung kaum berücksichtigt.","fa":"تاکنون این پرسش در پژوهش‌ها به‌ندرت مورد توجه قرار گرفته است.","note":"berücksichtigen = در نظر گرفتن؛ مجهول در گذشته."},{"de":"Im Gegensatz zu früheren Studien zeigt diese Untersuchung ein anderes Bild.","fa":"برخلاف پژوهش‌های پیشین، این بررسی تصویر متفاوتی نشان می‌دهد.","note":"im Gegensatz zu + Dativ = برخلاف."},{"de":"Es ist darauf hinzuweisen, dass die Stichprobe relativ klein war.","fa":"باید اشاره کرد که نمونه‌ی آماری نسبتاً کوچک بود.","note":"sein + zu + Infinitiv = «باید…» (رسمی)؛ Stichprobe = نمونه‌ی آماری."},{"de":"Zitate müssen immer mit einer genauen Quellenangabe versehen werden.","fa":"نقل‌قول‌ها همیشه باید با ذکر دقیق منبع همراه باشند.","note":"Quellenangabe = ذکر منبع؛ versehen mit = همراه کردن با."}]},{"day":80,"theme":"Prüfungen und Lernen","theme_fa":"امتحان و درس خواندن","s":[{"de":"Welche Themen kommen in der Prüfung dran?","fa":"چه مباحثی در امتحان می‌آید؟","note":"drankommen (محاوره) = در امتحان پرسیده شدن."},{"de":"Ich bin leider durch die mündliche Prüfung gefallen.","fa":"متأسفانه در امتحان شفاهی رد شدم.","note":"durchfallen با sein؛ durch die Prüfung fallen هم گفته می‌شود."},{"de":"Mit Karteikarten kann ich mir Vokabeln am besten merken.","fa":"با کارت‌های حافظه لغت‌ها را بهتر از هر روشی به خاطر می‌سپارم.","note":"sich etwas merken = چیزی را به خاطر سپردن."},{"de":"Ich hatte einen totalen Blackout, mir ist nichts mehr eingefallen.","fa":"ذهنم کاملاً قفل شد و دیگر هیچ چیز یادم نیامد.","note":"einfallen + Dativ = به ذهن رسیدن؛ Blackout = قفل شدن ذهن."},{"de":"Darf man in der Klausur ein Wörterbuch benutzen?","fa":"آیا در امتحان می‌شود از فرهنگ لغت استفاده کرد؟","note":"پرسش درباره‌ی وسایل مجاز امتحان (Hilfsmittel)."}]},{"day":81,"theme":"Bewerbung und Vorstellungsgespräch","theme_fa":"درخواست کار و مصاحبه‌ی استخدامی","s":[{"de":"Hiermit bewerbe ich mich um die Stelle als Softwareentwicklerin.","fa":"بدین‌وسیله برای موقعیت شغلی توسعه‌دهنده‌ی نرم‌افزار درخواست می‌دهم.","note":"sich bewerben um + Akkusativ؛ hiermit در نامه‌ی رسمی رایج است."},{"de":"Erzählen Sie doch mal etwas über sich.","fa":"کمی از خودتان بگویید.","note":"سؤال رایج آغاز مصاحبه؛ doch mal لحن را دوستانه می‌کند."},{"de":"Warum haben Sie sich gerade bei uns beworben?","fa":"چرا دقیقاً در شرکت ما درخواست داده‌اید؟","note":"سؤال رایج مصاحبه‌گر؛ gerade = دقیقاً."},{"de":"In meiner letzten Position war ich für die Kundenbetreuung zuständig.","fa":"در شغل قبلی‌ام مسئول ارتباط با مشتریان بودم.","note":"zuständig für = مسئول؛ برای توصیف سابقه‌ی کاری."},{"de":"Meine Gehaltsvorstellung liegt bei etwa 50.000 Euro brutto im Jahr.","fa":"حقوق مورد انتظارم حدود ۵۰ هزار یورو ناخالص در سال است.","note":"Gehaltsvorstellung = حقوق درخواستی؛ brutto = ناخالص."}]},{"day":82,"theme":"Im Büro: Meetings","theme_fa":"در دفتر: جلسه‌ها","s":[{"de":"Sind alle da? Dann können wir ja anfangen.","fa":"همه هستند؟ پس می‌توانیم شروع کنیم.","note":"ja اینجا حالت طبیعی و تأییدی دارد؛ شروع جلسه."},{"de":"Ich muss leider früher gehen, ich habe um drei noch einen Termin.","fa":"متأسفانه باید زودتر بروم، ساعت سه قرار دیگری دارم.","note":"عذرخواهی برای ترک زودهنگام جلسه."},{"de":"Können Sie das bitte noch einmal genauer erläutern?","fa":"ممکن است لطفاً این را کمی دقیق‌تر توضیح دهید؟","note":"erläutern = توضیح دادن؛ رسمی‌تر از erklären."},{"de":"Wir sollten beim Thema bleiben, sonst werden wir nicht fertig.","fa":"بهتر است از موضوع خارج نشویم، وگرنه کارمان تمام نمی‌شود.","note":"beim Thema bleiben = از موضوع منحرف نشدن."},{"de":"Bis zum nächsten Meeting klärt jeder seine offenen Punkte.","fa":"تا جلسه‌ی بعد هر کس کارهای باقی‌مانده‌ی خودش را روشن می‌کند.","note":"offene Punkte = موارد حل‌نشده؛ زمان حال برای آینده."}]},{"day":83,"theme":"Formelle E-Mails: Anfang und Schluss","theme_fa":"ایمیل رسمی: آغاز و پایان","s":[{"de":"Sehr geehrte Damen und Herren, ich schreibe Ihnen bezüglich meiner Bestellung.","fa":"با سلام و احترام، درباره‌ی سفارشم برایتان می‌نویسم.","note":"وقتی نام گیرنده را نمی‌دانید؛ bezüglich + Genitiv = درباره‌ی."},{"de":"Bezug nehmend auf unser Telefonat von gestern sende ich Ihnen das Angebot.","fa":"در پی تماس تلفنی دیروزمان، پیشنهاد قیمت را برایتان می‌فرستم.","note":"Bezug nehmend auf = با اشاره به؛ بسیار رسمی."},{"de":"Leider muss ich Ihnen mitteilen, dass der Termin nicht stattfinden kann.","fa":"متأسفانه باید به اطلاعتان برسانم که این قرار برگزار نمی‌شود.","note":"mitteilen = اطلاع دادن؛ برای رساندن خبر بد به شکل رسمی."},{"de":"Über eine baldige Antwort würde ich mich sehr freuen.","fa":"از پاسخ هر چه زودتر شما بسیار خوشحال خواهم شد.","note":"sich freuen über؛ درخواست مؤدبانه برای پاسخ سریع."},{"de":"Vielen Dank im Voraus und viele Grüße aus Hamburg.","fa":"پیشاپیش سپاسگزارم؛ با درود از هامبورگ.","note":"im Voraus = پیشاپیش؛ viele Grüße کمی صمیمی‌تر از Mit freundlichen Grüßen است."}]},{"day":84,"theme":"Mit Kollegen sprechen","theme_fa":"صحبت با همکاران","s":[{"de":"Hast du kurz Zeit? Ich bräuchte mal deine Meinung.","fa":"یک لحظه وقت داری؟ نظرت را لازم دارم.","note":"bräuchte (Konjunktiv II از brauchen) مؤدبانه‌تر است."},{"de":"Ich mache gleich Mittagspause, soll ich dir was mitbringen?","fa":"الان می‌روم ناهار، چیزی برایت بگیرم؟","note":"mitbringen = با خود آوردن؛ پیشنهاد دوستانه."},{"de":"Wie läuft's eigentlich mit deinem neuen Projekt?","fa":"راستی پروژه‌ی جدیدت چطور پیش می‌رود؟","note":"Wie läuft's? = اوضاع چطور است؟؛ eigentlich اینجا یعنی «راستی»."},{"de":"Sorry, dass ich störe, aber weißt du, wo der Schlüssel für den Konferenzraum ist?","fa":"ببخشید مزاحمت می‌شوم، می‌دانی کلید اتاق کنفرانس کجاست؟","note":"شروع مؤدبانه ولی غیررسمی با du؛ پرسش غیرمستقیم با wo."},{"de":"Schönen Feierabend und bis morgen!","fa":"عصر خوبی داشته باشی، تا فردا!","note":"Feierabend = پایان ساعت کاری؛ خداحافظی رایج در محل کار."}]},{"day":85,"theme":"Probleme bei der Arbeit lösen","theme_fa":"حل مشکلات کاری","s":[{"de":"Mir ist ein Fehler unterlaufen, die Zahlen in der Tabelle stimmen nicht.","fa":"اشتباهی از من سر زده؛ اعداد جدول درست نیستند.","note":"mir ist ein Fehler unterlaufen = اشتباهی از من سر زد؛ پذیرش مسئولیت."},{"de":"Wir sollten das Problem nicht auf die lange Bank schieben.","fa":"نباید حل این مشکل را عقب بیندازیم.","note":"auf die lange Bank schieben = کاری را به تعویق انداختن."},{"de":"Gibt es eine Übergangslösung, bis das System wieder läuft?","fa":"تا وقتی سیستم دوباره راه بیفتد، راه‌حل موقتی هست؟","note":"Übergangslösung = راه‌حل موقت."},{"de":"Ich habe das Problem an die IT-Abteilung weitergeleitet.","fa":"مشکل را به بخش فناوری اطلاعات ارجاع داده‌ام.","note":"weiterleiten = ارجاع دادن یا فوروارد کردن."},{"de":"Das hätten wir besser planen müssen, daraus lernen wir für das nächste Mal.","fa":"باید بهتر برنامه‌ریزی می‌کردیم؛ برای دفعه‌ی بعد از آن درس می‌گیریم.","note":"hätte … müssen = باید … می‌کردیم (Konjunktiv II گذشته)."}]},{"day":86,"theme":"Sich beschweren","theme_fa":"شکایت کردن","s":[{"de":"Die Heizung in meiner Wohnung funktioniert schon seit einer Woche nicht.","fa":"شوفاژ آپارتمانم از یک هفته پیش کار نمی‌کند.","note":"شکایت به صاحبخانه (Vermieter)؛ seit با زمان حال."},{"de":"Das kann doch nicht wahr sein, ich warte schon seit einer Stunde!","fa":"باورم نمی‌شود، یک ساعت است منتظرم!","note":"ابراز عصبانیت محاوره‌ای؛ doch تأکید می‌کند."},{"de":"Ich bitte Sie, sich so schnell wie möglich darum zu kümmern.","fa":"از شما خواهش می‌کنم هر چه زودتر به این موضوع رسیدگی کنید.","note":"درخواست رسمی و قاطع؛ jemanden bitten, … zu."},{"de":"Ich möchte gern mit Ihrem Vorgesetzten sprechen.","fa":"می‌خواهم با مسئول شما صحبت کنم.","note":"Vorgesetzte(r) = مافوق؛ وقتی کارمند نمی‌تواند کمک کند."},{"de":"Falls ich bis Ende des Monats nichts von Ihnen höre, werde ich rechtliche Schritte einleiten.","fa":"اگر تا پایان ماه خبری از شما نشود، اقدام قانونی خواهم کرد.","note":"rechtliche Schritte einleiten = اقدام قانونی کردن؛ آخرین مرحله‌ی شکایت."}]},{"day":87,"theme":"Verhandeln und Kompromisse finden","theme_fa":"مذاکره و پیدا کردن راه میانه","s":[{"de":"Ist am Preis noch etwas zu machen?","fa":"امکان تخفیف در قیمت هست؟","note":"پرسش محاوره‌ای و رایج برای چانه‌زنی."},{"de":"Das ist mein letztes Angebot.","fa":"این آخرین پیشنهاد من است.","note":"یعنی دیگر بیشتر از این کوتاه نمی‌آیم."},{"de":"Ich komme Ihnen beim Termin entgegen, wenn Sie beim Preis nachgeben.","fa":"در زمان‌بندی با شما راه می‌آیم، به شرط اینکه در قیمت کوتاه بیایید.","note":"nachgeben = کوتاه آمدن؛ الگوی معامله‌ی دوطرفه."},{"de":"Darüber müsste ich erst mit meinem Team sprechen.","fa":"درباره‌ی این باید اول با تیمم صحبت کنم.","note":"برای خریدن زمان در مذاکره؛ müsste = Konjunktiv II."},{"de":"Gut, dann haben wir einen Deal.","fa":"خب، پس توافق کردیم.","note":"پایان محاوره‌ای مذاکره؛ رسمی‌تر: Dann sind wir uns einig."}]},{"day":88,"theme":"Über Erfahrungen berichten","theme_fa":"تعریف کردن تجربه‌ها","s":[{"de":"Letztes Jahr habe ich ein Auslandssemester in Wien gemacht.","fa":"سال گذشته یک ترم را در وین گذراندم.","note":"Auslandssemester = ترم تحصیلی در خارج؛ Perfekt در گفتار رایج است."},{"de":"Das war eine der besten Erfahrungen meines Lebens.","fa":"این یکی از بهترین تجربه‌های زندگی‌ام بود.","note":"eine der + صفت عالی + اسم جمع."},{"de":"Anfangs hatte ich Schwierigkeiten, den Dialekt zu verstehen.","fa":"اوایل در فهمیدن لهجه مشکل داشتم.","note":"Schwierigkeiten haben, … zu = در انجام کاری مشکل داشتن."},{"de":"Damals hätte ich nie gedacht, dass ich einmal hier leben würde.","fa":"آن موقع هرگز فکرش را نمی‌کردم روزی اینجا زندگی کنم.","note":"hätte nie gedacht = هرگز فکرش را نمی‌کردم."},{"de":"Daraus habe ich gelernt, immer einen Plan B zu haben.","fa":"از آن ماجرا یاد گرفتم که همیشه یک برنامه‌ی جایگزین داشته باشم.","note":"lernen aus + Dativ؛ daraus = از آن تجربه."}]},{"day":89,"theme":"Pläne und Ziele beschreiben","theme_fa":"توصیف برنامه‌ها و هدف‌ها","s":[{"de":"Ich hoffe, dass ich bald eine feste Stelle finde.","fa":"امیدوارم به‌زودی یک شغل دائمی پیدا کنم.","note":"feste Stelle = شغل دائم؛ متضاد: befristete Stelle."},{"de":"In fünf Jahren sehe ich mich in einer leitenden Position.","fa":"پنج سال دیگر خودم را در یک سمت مدیریتی می‌بینم.","note":"پاسخ به سؤال رایج مصاحبه؛ leitend = مدیریتی."},{"de":"Ich habe mir fest vorgenommen, mehr mit Muttersprachlern zu sprechen.","fa":"تصمیم جدی گرفته‌ام بیشتر با آلمانی‌زبان‌ها صحبت کنم.","note":"sich etwas vornehmen = تصمیم گرفتن، قصد کردن."},{"de":"Wenn alles nach Plan läuft, ziehen wir im Frühling um.","fa":"اگر همه‌چیز طبق برنامه پیش برود، بهار اسباب‌کشی می‌کنیم.","note":"nach Plan laufen = طبق برنامه پیش رفتن؛ umziehen جداشدنی است."},{"de":"Dafür muss ich aber erst einmal genug Geld sparen.","fa":"ولی برای این کار اول باید به اندازه‌ی کافی پول جمع کنم.","note":"erst einmal = اول از همه؛ dafür = برای آن هدف."}]},{"day":90,"theme":"Vor- und Nachteile abwägen","theme_fa":"سنجیدن مزایا و معایب","s":[{"de":"Das hat sowohl Vor- als auch Nachteile.","fa":"این هم مزایا دارد و هم معایب.","note":"sowohl … als auch = هم … هم؛ خط تیره در Vor- جای تکرار را می‌گیرد."},{"de":"Was spricht eigentlich dagegen, das Auto zu verkaufen?","fa":"اصلاً چه دلیلی برای نفروختن ماشین وجود دارد؟","note":"etwas spricht dafür/dagegen = دلیلی به نفع/علیه چیزی هست."},{"de":"Auf der einen Seite spart man Zeit, auf der anderen Seite kostet es mehr.","fa":"از یک طرف وقت آدم ذخیره می‌شود، از طرف دیگر گران‌تر تمام می‌شود.","note":"جایگزین رایج برای einerseits … andererseits."},{"de":"Der entscheidende Vorteil liegt in der Flexibilität.","fa":"مزیت تعیین‌کننده در انعطاف‌پذیری است.","note":"liegen in + Dativ = نهفته بودن در."},{"de":"Ich bin hin- und hergerissen und kann mich nicht entscheiden.","fa":"سر دوراهی مانده‌ام و نمی‌توانم تصمیم بگیرم.","note":"hin- und hergerissen sein = دودل بودن."}]},{"day":91,"theme":"Grafiken und Statistiken beschreiben","theme_fa":"توصیف نمودارها و آمار","s":[{"de":"Auf der x-Achse sind die Jahre, auf der y-Achse die Einnahmen abgebildet.","fa":"روی محور x سال‌ها و روی محور y درآمدها نشان داده شده‌اند.","note":"abgebildet sein = نمایش داده شدن؛ Achse = محور."},{"de":"Die Zahl der Arbeitslosen ist im Vergleich zum Vorjahr leicht gesunken.","fa":"تعداد بیکاران در مقایسه با سال قبل اندکی کاهش یافته است.","note":"im Vergleich zu = در مقایسه با؛ sinken با sein."},{"de":"Den größten Anteil machen mit 40 Prozent die Online-Käufe aus.","fa":"خریدهای اینترنتی با ۴۰ درصد بیشترین سهم را دارند.","note":"ausmachen = تشکیل دادن؛ مناسب نمودار دایره‌ای."},{"de":"Die Kurve erreicht im Jahr 2015 ihren Höhepunkt.","fa":"منحنی در سال ۲۰۱۵ به اوج خود می‌رسد.","note":"den Höhepunkt/Tiefpunkt erreichen = به اوج/پایین‌ترین نقطه رسیدن."},{"de":"Die Werte sind in den letzten Jahren relativ konstant geblieben.","fa":"مقادیر در سال‌های اخیر نسبتاً ثابت مانده‌اند.","note":"konstant bleiben = ثابت ماندن؛ بدون تغییر محسوس."}]},{"day":92,"theme":"Zusammenfassen","theme_fa":"خلاصه کردن","s":[{"de":"Der Text handelt von einer Familie, die nach Kanada auswandert.","fa":"متن درباره‌ی خانواده‌ای است که به کانادا مهاجرت می‌کند.","note":"handeln von + Dativ = درباره‌ی چیزی بودن (برای متن، کتاب و فیلم)."},{"de":"Ich fasse das Wichtigste in ein paar Sätzen zusammen.","fa":"مهم‌ترین مطالب را در چند جمله خلاصه می‌کنم.","note":"zusammenfassen جداشدنی است؛ das Wichtigste = مهم‌ترین چیزها."},{"de":"Die zentrale Aussage des Artikels ist, dass Arbeit krank machen kann.","fa":"پیام اصلی مقاله این است که کار می‌تواند آدم را بیمار کند.","note":"zentrale Aussage = پیام اصلی متن."},{"de":"Mit anderen Worten: Wir müssen sparen.","fa":"به عبارت دیگر: باید صرفه‌جویی کنیم.","note":"mit anderen Worten = به بیان دیگر؛ برای ساده کردن مطلب."},{"de":"Darüber hinaus nennt die Autorin mehrere konkrete Beispiele.","fa":"علاوه بر این، نویسنده چند مثال مشخص هم ذکر می‌کند.","note":"darüber hinaus = علاوه بر این؛ رسمی و نوشتاری."}]},{"day":93,"theme":"Nachrichten und Politik","theme_fa":"اخبار و سیاست","s":[{"de":"Hast du schon gehört? Die Wahlen werden vorgezogen.","fa":"شنیده‌ای؟ انتخابات زودتر برگزار می‌شود.","note":"vorziehen = جلو انداختن؛ اینجا مجهول حال."},{"de":"Ich informiere mich meistens über Podcasts und Online-Zeitungen.","fa":"معمولاً از طریق پادکست و روزنامه‌های آنلاین خبر می‌گیرم.","note":"sich informieren = کسب اطلاع کردن؛ über اینجا یعنی «از طریق»."},{"de":"Die Opposition kritisiert den Vorschlag scharf.","fa":"اپوزیسیون این پیشنهاد را به‌شدت نقد می‌کند.","note":"scharf kritisieren = به‌شدت انتقاد کردن؛ زبان اخبار."},{"de":"Über Politik rede ich eigentlich nicht so gern.","fa":"راستش زیاد دوست ندارم درباره‌ی سیاست حرف بزنم.","note":"راهی مؤدبانه برای دوری از بحث سیاسی."},{"de":"Meiner Meinung nach wird über dieses Thema viel zu wenig berichtet.","fa":"به نظر من درباره‌ی این موضوع خیلی کم گزارش می‌شود.","note":"berichten über؛ مجهول بدون فاعل با wird."}]},{"day":94,"theme":"Umwelt und Nachhaltigkeit","theme_fa":"محیط زیست و پایداری","s":[{"de":"Wir haben unseren Fleischkonsum deutlich reduziert.","fa":"مصرف گوشتمان را به‌طور محسوسی کم کرده‌ایم.","note":"reduzieren = کاهش دادن؛ Konsum = مصرف."},{"de":"Vergiss nicht, die Pfandflaschen zurückzubringen.","fa":"یادت نرود بطری‌های پانت‌دار را برگردانی.","note":"Pfand = ودیعه‌ی بطری؛ در فعل جداشدنی zu وسط می‌آید."},{"de":"Mehr Bäume in der Stadt würden die Luftqualität verbessern.","fa":"درختان بیشتر در شهر کیفیت هوا را بهتر می‌کرد.","note":"würden + Infinitiv برای فرض و پیشنهاد."},{"de":"Es reicht nicht, wenn nur Einzelne etwas ändern, die Industrie muss mitziehen.","fa":"کافی نیست فقط چند نفر چیزی را تغییر دهند؛ صنعت هم باید همراهی کند.","note":"mitziehen = همراهی کردن؛ Einzelne = افراد منفرد."},{"de":"Statt etwas Neues zu kaufen, lasse ich alte Sachen lieber reparieren.","fa":"به جای خرید چیز نو، ترجیح می‌دهم وسایل قدیمی را بدهم تعمیر کنند.","note":"statt … zu = به جای؛ lassen + Infinitiv = دادن کاری به دیگری."}]},{"day":95,"theme":"Gesundheit und Sport","theme_fa":"سلامت و ورزش","s":[{"de":"Ich hätte gern einen Termin, möglichst noch diese Woche.","fa":"یک وقت می‌خواستم، اگر شود همین هفته.","note":"تلفن به مطب؛ möglichst = در صورت امکان."},{"de":"Mir ist schwindelig und ich habe Kopfschmerzen.","fa":"سرم گیج می‌رود و سردرد دارم.","note":"Mir ist schwindelig با Dativ، نه ich bin."},{"de":"Wie oft am Tag soll ich die Tabletten nehmen?","fa":"قرص‌ها را روزی چند بار باید بخورم؟","note":"Tabletten nehmen = قرص خوردن (نه essen)."},{"de":"Nach dem Training habe ich einen ordentlichen Muskelkater.","fa":"بعد از تمرین حسابی بدنم کوفته شده.","note":"Muskelkater = درد عضلانی پس از ورزش."},{"de":"Ich achte inzwischen mehr auf meine Ernährung.","fa":"حالا دیگر بیشتر به تغذیه‌ام توجه می‌کنم.","note":"achten auf + Akkusativ؛ inzwischen = حالا دیگر."}]},{"day":96,"theme":"Digitales Leben und Medien","theme_fa":"زندگی دیجیتال و رسانه‌ها","s":[{"de":"Ich lösche jetzt mal ein paar Apps, die ich nie benutze.","fa":"حالا چندتا از برنامه‌هایی را که هیچ‌وقت استفاده نمی‌کنم پاک می‌کنم.","note":"löschen = پاک کردن؛ mal لحن را محاوره‌ای می‌کند."},{"de":"Kannst du mich zur Gruppe hinzufügen?","fa":"می‌توانی من را به گروه اضافه کنی؟","note":"hinzufügen zu = اضافه کردن به؛ رایج در پیام‌رسان‌ها."},{"de":"Die Verbindung ist ganz schlecht, ich verstehe dich kaum.","fa":"اتصال خیلی بد است، صدایت را به‌زحمت می‌شنوم.","note":"مناسب تماس تصویری؛ kaum = به‌سختی."},{"de":"Viele Jugendliche stehen unter Druck, in sozialen Netzwerken perfekt zu wirken.","fa":"بسیاری از نوجوانان زیر فشارند که در شبکه‌های اجتماعی بی‌نقص به نظر برسند.","note":"unter Druck stehen = تحت فشار بودن؛ wirken = به نظر رسیدن."},{"de":"Am Wochenende mache ich bewusst eine digitale Pause.","fa":"آخر هفته‌ها آگاهانه از دنیای دیجیتال فاصله می‌گیرم.","note":"bewusst = آگاهانه؛ Digital Detox هم گفته می‌شود."}]},{"day":97,"theme":"Kultur und Freizeit","theme_fa":"فرهنگ و اوقات فراغت","s":[{"de":"Was machst du so in deiner Freizeit?","fa":"در اوقات فراغتت معمولاً چه کار می‌کنی؟","note":"so اینجا یعنی «معمولاً، مثلاً»؛ سؤال رایج small talk."},{"de":"Ich bin kein großer Fan von Opern, aber das Konzert war toll.","fa":"من طرفدار پروپاقرص اپرا نیستم، ولی کنسرت عالی بود.","note":"kein großer Fan von = علاقه‌ی زیادی نداشتن."},{"de":"Am Wochenende findet in der Altstadt ein Weinfest statt.","fa":"آخر هفته در محله‌ی قدیمی شهر یک جشن شراب برگزار می‌شود.","note":"stattfinden = برگزار شدن؛ فعل جداشدنی."},{"de":"Das Museum hat montags geschlossen.","fa":"موزه دوشنبه‌ها تعطیل است.","note":"montags = دوشنبه‌ها؛ بسیاری از موزه‌های آلمان دوشنبه بسته‌اند."},{"de":"Ich kann dir den Roman nur empfehlen, er ist richtig spannend.","fa":"این رمان را حتماً بخوان، خیلی پرکشش است.","note":"nur empfehlen können = قویاً توصیه کردن."}]},{"day":98,"theme":"Interkulturelle Missverständnisse","theme_fa":"سوءتفاهم‌های بین‌فرهنگی","s":[{"de":"Bei uns zieht man die Schuhe aus, bevor man die Wohnung betritt.","fa":"پیش ما آدم پیش از ورود به خانه کفش‌هایش را درمی‌آورد.","note":"توضیح یک رسم فرهنگی؛ bevor = پیش از اینکه."},{"de":"Ist es hier üblich, Trinkgeld zu geben?","fa":"اینجا انعام دادن مرسوم است؟","note":"üblich = مرسوم؛ در رستوران‌های آلمان حدود ۵ تا ۱۰ درصد."},{"de":"Ich habe den Eindruck, dass Sie mich falsch verstanden haben.","fa":"احساس می‌کنم حرفم را اشتباه متوجه شدید.","note":"den Eindruck haben = برداشتی داشتن؛ مؤدبانه و غیرمستقیم."},{"de":"Bei euch sagt man also gleich Bescheid, wenn einem etwas nicht passt?","fa":"پس پیش شما رسم است اگر چیزی خوشتان نیاید همان موقع بگویید؟","note":"Bescheid sagen = خبر دادن؛ passen + Dativ = مناسب بودن."},{"de":"Am Anfang fand ich die Deutschen etwas distanziert, aber das hat sich geändert.","fa":"اوایل آلمانی‌ها را کمی خوددار و سرد می‌دیدم، اما این عوض شد.","note":"distanziert = خوددار؛ sich ändern = تغییر کردن."}]},{"day":99,"theme":"Ärger und Konflikte entschärfen","theme_fa":"آرام کردن خشم و تنش","s":[{"de":"Mir geht es nicht darum, wer recht hat, sondern um eine Lösung.","fa":"برای من مهم نیست حق با کیست؛ دنبال راه‌حلم.","note":"es geht mir um = برایم مهم است؛ recht haben = حق داشتن."},{"de":"Vielleicht habe ich mich unglücklich ausgedrückt.","fa":"شاید منظورم را بد بیان کردم.","note":"sich ausdrücken = بیان کردن؛ پذیرش مسئولیت برای کاهش تنش."},{"de":"Komm, lass uns nicht wegen so einer Kleinigkeit streiten.","fa":"بیا، سر یک چیز کوچک دعوا نکنیم.","note":"wegen + Genitiv (در محاوره Dativ)؛ Kleinigkeit = چیز جزئی."},{"de":"Ich kann deinen Standpunkt nachvollziehen, sehe es aber anders.","fa":"دیدگاهت را درک می‌کنم، ولی خودم جور دیگری می‌بینم.","note":"nachvollziehen = درک کردن استدلال کسی."},{"de":"Lass uns das Thema vertagen, bis wir uns beide beruhigt haben.","fa":"بیا این بحث را بگذاریم برای بعد، وقتی هر دو آرام شدیم.","note":"vertagen = به وقت دیگری موکول کردن."}]},{"day":100,"theme":"Redewendungen im Alltag","theme_fa":"اصطلاحات روزمره","s":[{"de":"Das ist doch nur ein Katzensprung von hier.","fa":"از اینجا فقط دو قدم راه است.","note":"Katzensprung = فاصله‌ی خیلی کوتاه."},{"de":"Er hat mal wieder den Nagel auf den Kopf getroffen.","fa":"او باز هم دقیقاً حرف حساب را زد.","note":"den Nagel auf den Kopf treffen = دقیقاً به اصل مطلب زدن."},{"de":"Jetzt habe ich aber die Nase voll!","fa":"دیگر کارد به استخوانم رسیده!","note":"die Nase voll haben = از چیزی خسته و کلافه شدن."},{"de":"Das ist mir Wurst.","fa":"برایم فرقی نمی‌کند.","note":"محاوره‌ای = برایم مهم نیست؛ فقط در جمع دوستانه."},{"de":"Wir sitzen alle im selben Boot.","fa":"همه‌ی ما در یک کشتی نشسته‌ایم.","note":"im selben Boot sitzen = سرنوشت مشترک داشتن."}]}];
